99	// Convert structured custom ops after operand type converted,
100	// for example tt.ptr converted to memref.
101	template <typename CustomOpT>
102	class StructuredCustomOpConverter : public OpConversionPattern<CustomOpT> {
103	public:
104	  using OpConversionPattern<CustomOpT>::OpConversionPattern;
105	
106	  LogicalResult
107	  matchAndRewrite(CustomOpT op, typename CustomOpT::Adaptor adaptor,
108	                  ConversionPatternRewriter &rewriter) const override {
109	    BlockDataParser::rewriteStructuredCustomOp(op, adaptor, rewriter);
110	    return success();
111	  }
