114	// A tt.scan that is (1) a plain cumsum (combine body is a single add, matching
115	// ScanConverter's triton_cumsum selection) and (2) collapses to a 1-D scan
116	// after backend lowering, i.e. every dim except the scan axis has extent 1
117	// (e.g. [1,1,128,1] with axis=2). Only this case is routed to the SIMT
118	// (Sklansky) cumsum template; cumprod / generic scans and multi-dim cumsum stay
119	// on SIMD.
120	static bool isSimt1DCumsum(triton::ScanOp op) {
121	  // (1) Must be a single-add combine body (skip pure type-cast ops, mirroring
122	  // ReductionOpBaseConverter::getRealReductionOps).
123	  Operation *reduceOp = nullptr;
124	  for (Operation &bodyOp : op.getBody()->without_terminator()) {
125	    if (isa<arith::ExtFOp, arith::TruncFOp, arith::BitcastOp>(&bodyOp))
126	      continue;
127	    if (reduceOp)
128	      return false; // more than one real op -> not a simple cumsum
129	    reduceOp = &bodyOp;
130	  }
131	  if (!reduceOp || !isa<arith::AddFOp, arith::AddIOp>(reduceOp))
132	    return false;
133	
134	  // (2) Must be the 1-D scenario: all non-scan dims are unit-sized.
135	  auto srcTy = dyn_cast<RankedTensorType>(op.getOperand(0).getType());
136	  if (!srcTy || !srcTy.hasRank())
137	    return false;
138	  int64_t axis = op.getAxis();
139	  ArrayRef<int64_t> shape = srcTy.getShape();
140	  if (axis < 0 || axis >= static_cast<int64_t>(shape.size()))
141	    return false;
142	  for (int64_t i = 0; i < static_cast<int64_t>(shape.size()); ++i) {
143	    if (i != axis && shape[i] != 1)
144	      return false;
145	  }
146	  return true;
147	}
