149	static bool isCustomOpOperandTypesLegal(TypeRange types) {
150	  return llvm::all_of(types, [](Type t) {
151	    if (isa<triton::PointerType>(t)) {
152	      return false;
153	    }
154	    if (auto shapedType = dyn_cast<ShapedType>(t)) {
155	      return !isa<triton::PointerType>(shapedType.getElementType());
156	    }
157	    return true;
158	  });
159	}
