161	static bool isSIMTOp(Operation *op) {
162	  if (auto custom_op = dyn_cast<hivm::CustomOp>(op)) {
163	    return custom_op.getCoreType() == hivm::TCoreType::VECTOR &&
164	           custom_op.getVFMode() == hivm::VFMode::SIMT;
165	  }
166	
167	  if (isa<triton::GatherOp>(op) && compileOn91095Flag) {
168	    return true;
169	  }
170	
171	  if (isa<triton::HistogramOp>(op) && compileOn91095Flag) {
172	    return true;
173	  }
174	
175	  // tt.scan: only a 1-D cumsum is treated as a SIMT op (drives the kernel
176	  // parallel_mode -> mix_simd_simt -> enable_simt). Everything else stays SIMD.
177	  if (compileOn91095Flag) {
178	    if (auto scan = dyn_cast<triton::ScanOp>(op)) {
179	      return isSimt1DCumsum(scan);
180	    }
181	  }
182	  return isa<triton::ascend::IndexPutOp, triton::ascend::GatherOutToUbOp,
183	             triton::ascend::ScatterUbToOutOp, triton::ascend::IndirectLoadOp,
184	             triton::ascend::StrideLoadOp, triton::ascend::StrideStoreOp,
185	             triton::ascend::IndirectStoreOp>(op);
186	}
