188	TritonTypeConverter::TritonTypeConverter() {
189	  addConversion([](Type type) { return type; });
190	
191	  addConversion([](triton::PointerType ptrType) {
192	    Type elem = ptrType.getPointeeType();
193	    // Handling special case: ptr<i1> -> memref<?x i8>
194	    if (auto it = dyn_cast<IntegerType>(elem); it && it.getWidth() == 1) {
195	      elem = IntegerType::get(ptrType.getContext(), 8);
196	      LLVM_DEBUG({
197	        llvm::dbgs() << "[TritonTypeConverter] Normalize i1 pointer to i8 "
198	                        "memref. elemType="
199	                     << elem << "\n";
200	      });
201	    }
202	    return MemRefType::get({ShapedType::kDynamic}, elem);
203	  });
204	
205	  addConversion([](TensorType tensorType) -> Type {
206	    auto elemType = tensorType.getElementType();
207	    if (auto ptrType = dyn_cast<triton::PointerType>(elemType)) {
208	      elemType = ptrType.getPointeeType();
209	    }
210	    // Handling special case: tensor<i1> -> memref<?x i8>
211	    if (auto it = dyn_cast<IntegerType>(elemType); it && it.getWidth() == 1) {
212	      elemType = IntegerType::get(tensorType.getContext(), 8);
213	      LLVM_DEBUG({
214	        llvm::dbgs() << "[TritonTypeConverter] Normalize i1 tensor to i8 "
215	                        "memref. elemType="
216	                     << elemType << "\n";
217	      });
218	    }
219	    return MemRefType::get(tensorType.getShape(), elemType);
220	  });
221	}
