223	void TritonToLinalgPass::addProgramInfo(triton::FuncOp func,
224	                                        bool globalKernel) {
225	  OpBuilder b(func);
226	
227	  auto origFuncType = func.getFunctionType();
228	  auto origInputTypes = origFuncType.getInputs();
229	  SmallVector<Type> newInputTypes(origInputTypes);
230	  newInputTypes.append(TRITON_PROGRAM_INFO_ARG_COUNT, b.getI32Type());
231	
232	  auto newFuncType =
233	      b.getFunctionType(newInputTypes, origFuncType.getResults());
234	
235	  func.setFunctionType(newFuncType);
236	
237	  // If argument attributes exist, extend attribute list.
238	  if (func.getAllArgAttrs()) {
239	    SmallVector<DictionaryAttr> newArgAttrs;
240	    func.getAllArgAttrs(newArgAttrs);
241	    newArgAttrs.append(TRITON_PROGRAM_INFO_ARG_COUNT, DictionaryAttr());
242	    func.setAllArgAttrs(newArgAttrs);
243	  }
244	
245	  // Append the arguments to the entry block.
246	  for (unsigned i = 0; i < TRITON_PROGRAM_INFO_ARG_COUNT; i++) {
247	    func.getBody().front().addArgument(b.getI32Type(), func.getLoc());
248	  }
249	
250	  if (globalKernel) {
251	    func->setAttr(globalKernelAttr, b.getStringAttr(""));
252	  } else {
253	    func->setAttr(globalKernelAttr, b.getStringAttr("local"));
254	  }
255	}
