257	LogicalResult
258	TritonToLinalgPass::convertMultipleBlockControlFlow(Operation *funcOp,
259	                                                    OpBuilder &builder) {
260	  if (!isa<func::FuncOp>(funcOp)) {
261	    funcOp->emitError(
262	        "convertMultipleBlockControlFlow can only process func::FuncOp!");
263	    return failure();
264	  }
265	
266	  SmallVector<Operation *> candidate;
267	  SmallVector<Block *> eraseBlocks;
268	  for (Block &block : dyn_cast<func::FuncOp>(funcOp).getBody()) {
269	    auto curTerminator = block.getTerminator();
270	    if (isa<cf::CondBranchOp>(curTerminator)) {
271	      candidate.push_back(curTerminator);
272	    } else if (isa<triton::ReturnOp>(curTerminator)) {
273	      if (candidate.empty()) {
274	        curTerminator->emitError(
275	            "funcOp has more than one Block but got an early 'tt.return' Op.");
276	        return failure();
277	      }
278	    } else if (!isa<cf::BranchOp>(curTerminator)) {
279	      funcOp->emitError(
280	          "funcOp has more than one Block but found unsupported Terminator: ")
281	          << *curTerminator;
282	      return failure();
283	    }
284	
285	    if (!block.isEntryBlock())
286	      eraseBlocks.push_back(&block);
287	  }
288	
289	  LLVM_DEBUG({
290	    llvm::dbgs() << "Found " << candidate.size()
291	                 << " candidate cond_branch operations to convert.\n";
292	  });
293	
294	  if (candidate.empty()) {
295	    funcOp->emitError("funcOp has more than one Block but no candidate "
296	                      "Terminator was found!");
297	    return failure();
298	  }
299	
300	  llvm::BitVector visitFlag(candidate.size(), false);
301	
302	  // Recursive function to convert all cf::CondBranchOp to scf::IfOp
303	  std::function<void(Operation *, Operation *)> convertToSCF =
304	      [&](Operation *op, Operation *insertPosOp) -> void {
305	    auto condBranchOp = dyn_cast_if_present<cf::CondBranchOp>(op);
306	    auto iter = llvm::find(candidate, condBranchOp);
307	    if (!(condBranchOp && iter != candidate.end())) {
308	      op->emitError(
309	          "convertToSCF must process with condBranchOp in candidates!");
310	      return;
311	    }
312	    visitFlag.set(iter - candidate.begin());
313	
314	    OpBuilder::InsertionGuard guard(builder);
315	    builder.setInsertionPointAfter(insertPosOp);
316	
317	    // Well, here force to destory original control flow
318	    builder.create<scf::IfOp>(
319	        condBranchOp->getLoc(), condBranchOp.getCondition(),
320	        /*thenBuilder=*/
321	        [&](OpBuilder &builder, Location loc) {
322	          SmallVector<Operation *> movedOps = llvm::map_to_vector(
323	              condBranchOp.getTrueDest()->without_terminator(),
324	              [](Operation &op) { return &op; });
325	          for (auto *innerOp : movedOps) {
326	            innerOp->moveBefore(builder.getInsertionBlock(),
327	                                builder.getInsertionPoint());
328	          }
329	
330	          auto blockTerm = condBranchOp.getTrueDest()->getTerminator();
331	          if (auto nextCond = dyn_cast<cf::CondBranchOp>(blockTerm)) {
332	            if (movedOps.empty()) {
333	              blockTerm->emitError("movedOps can not be empty before entering "
334	                                   "convertToSCF (then)!");
335	              return;
336	            }
337	            convertToSCF(nextCond, movedOps.back());
338	          } else if (!isa<cf::BranchOp, triton::ReturnOp>(blockTerm)) {
339	            blockTerm->emitError(
340	                "Unsupported terminator in then branch after structuring");
341	          }
342	
343	          builder.create<scf::YieldOp>(loc);
344	        },
345	        /*elseBuilder=*/
346	        [&](OpBuilder &builder, Location loc) {
347	          SmallVector<Operation *> movedOps = llvm::map_to_vector(
348	              condBranchOp.getFalseDest()->without_terminator(),
349	              [](Operation &op) { return &op; });
350	          for (auto *innerOp : movedOps) {
351	            innerOp->moveBefore(builder.getInsertionBlock(),
352	                                builder.getInsertionPoint());
353	          }
354	
355	          auto blockTerm = condBranchOp.getFalseDest()->getTerminator();
356	          if (auto nextCond = dyn_cast<cf::CondBranchOp>(blockTerm)) {
357	            if (movedOps.empty()) {
358	              blockTerm->emitError("movedOps can not be empty before entering "
359	                                   "convertToSCF (else)!");
360	              return;
361	            }
362	            convertToSCF(nextCond, movedOps.back());
363	          } else if (!isa<cf::BranchOp, triton::ReturnOp>(blockTerm)) {
364	            blockTerm->emitError(
365	                "Unsupported terminator in else branch after structuring");
366	          }
367	          builder.create<scf::YieldOp>(loc);
368	        });
369	  };
370	
371	  Block::iterator insertOp(candidate.front());
372	  if (insertOp == candidate.front()->getBlock()->begin()) {
373	    // if the first operation is a cond_branch, we need to insert before it
374	    convertToSCF(candidate.front(), candidate.front());
375	  } else {
376	    --insertOp;
377	    convertToSCF(candidate.front(), &(*insertOp));
378	  }
379	
380	  if (!visitFlag.all()) {
381	    funcOp->emitError("Not all cf.cond_br converted!");
382	    return failure();
383	  }
384	
385	  OpBuilder::InsertionGuard guard(builder);
386	  builder.setInsertionPoint(candidate.front());
387	  builder.create<triton::ReturnOp>(candidate.front()->getLoc());
388	
389	  for (Operation *eachTerm : candidate)
390	    eachTerm->erase();
391	  for (Block *block : llvm::reverse(eraseBlocks))
392	    block->erase();
393	
394	  return success();
395	}
