397	void TritonToLinalgPass::convertTTFunc(triton::FuncOp func, const bool existDot,
398	                                       const bool existSIMTOp) {
399	  OpBuilder builder(func);
400	
401	  auto name = func.getName();
402	  auto type = func.getFunctionType();
403	
404	  SmallVector<DictionaryAttr> argAttrs, resAttrs;
405	  func.getAllArgAttrs(argAttrs);
406	  func.getAllResultAttrs(resAttrs);
407	
408	  // Special handling for bit-casted tt.ptr arguments
409	  SmallVector<Type> inputTypes{type.getInputs()};
410	  SmallVector<Type> retTypes{type.getResults()};
411	  if (func.getSymVisibility() == "public" && !func.isDeclaration()) {
412	    for (size_t i = 0; i < func.getNumArguments(); ++i) {
413	      auto arg = func.getArgument(i);
414	      // Special method for i1 arg
415	      if (!isa<BaseMemRefType>(arg.getType()) ||
416	          dyn_cast<BaseMemRefType>(arg.getType()).getElementTypeBitWidth() !=
417	              1) {
418	        continue;
419	      }
420	
421	      SmallVector<Operation *> argVaildUser{arg.getUsers()};
422	      llvm::erase_if(argVaildUser, [](Operation *op) -> bool {
423	        return isOpTriviallyDead(op);
424	      });
425	
426	      if (!argVaildUser.empty()) {
427	        LLVM_DEBUG({
428	          auto &os = llvm::dbgs();
429	          os << arg << " has users:\n";
430	          int cnt = 0;
431	          for (auto it : argVaildUser) {
432	            os << "users[" << cnt++ << "] = " << *it;
433	          }
434	        });
435	        if (llvm::all_of(argVaildUser, [](Operation *userOp) {
436	              return isa<UnrealizedConversionCastOp>(userOp);
437	            })) {
438	          auto castOp = cast<UnrealizedConversionCastOp>(*argVaildUser.begin());
439	          if (castOp.getInputs().size() == 1 &&
440	              castOp.getOutputs().size() == 1) {
441	            arg.setType(castOp.getOutputs()[0].getType());
442	            inputTypes[i] = arg.getType();
443	          }
444	        } else {
445	          func->emitError(Twine("Unsupported use of func arg at index ") +
446	                          Twine(i));
447	        }
448	      } else {
449	        // Process unused bool ptr type specially, which guarantees bool pointer
450	        // argument's type is realistic and don't mislead backend compiler.
451	        // realistic memory layout of bool pointer is 8 bit width
452	        auto memType = dyn_cast<BaseMemRefType>(arg.getType())
453	                           .cloneWith(std::nullopt, builder.getI8Type());
454	        arg.setType(memType);
455	        inputTypes[i] = arg.getType();
456	      }
457	    }
458	  }
459	  auto castType = FunctionType::get(func.getContext(), inputTypes, retTypes);
460	
461	  auto funcFunc = builder.create<func::FuncOp>(func.getLoc(), name, castType);
462	  funcFunc.setAllArgAttrs(argAttrs);
463	  funcFunc.setAllResultAttrs(resAttrs);
464	  auto kernelAttr = func->getAttr(globalKernelAttr);
465	  if (kernelAttr) {
466	    funcFunc->setAttr(globalKernelAttr, kernelAttr);
467	  }
468	  std::string kernelMixMode = "aiv";
469	  if (existDot) {
470	    // mix also works for pure cube kernel by using the same MAGIC_ELF keyword
471	    kernelMixMode = "mix";
472	  }
473	  // Set mix_mode in the func attrs so that the backend could know
474	  // the mix_mode by parse the func attrs.
475	  // The backend needs to know the mix_mode because the host wrapper
476	  // needs to set the devbin.magic. Check npu_utils.cpp.
477	  funcFunc->setAttr(kernelMixModeName, builder.getStringAttr(kernelMixMode));
478	
479	  std::string parallelMode = "simd";
480	  if (existSIMTOp) {
481	    parallelMode = "mix_simd_simt";
482	  }
483	  funcFunc->setAttr(kernelParallelModeName,
484	                    builder.getStringAttr(parallelMode));
485	
486	  auto autoBlockifyAttr = func->getAttr("auto_blockify_size");
487	  if (autoBlockifyAttr)
488	    funcFunc->setAttr("auto_blockify_size", autoBlockifyAttr);
489	
490	  auto &funcFuncBody = funcFunc.getBody();
491	  auto &funcBody = func.getBody();
492	
493	  IRMapping map;
494	  funcBody.cloneInto(&funcFuncBody, map);
495	
496	  if (!funcFuncBody.hasOneBlock()) {
497	    if (failed(convertMultipleBlockControlFlow(funcFunc, builder))) {
498	      llvm_unreachable("Encounter unsupported control flow");
499	    }
500	  }
501	
502	  for (Block &block : funcFuncBody.getBlocks()) {
503	    auto term = block.getTerminator();
504	    builder.setInsertionPoint(term);
505	    builder.create<func::ReturnOp>(func.getLoc(), term->getOperands());
506	    term->erase();
507	  }
508	  func.erase();
509	}
