511	void TritonToLinalgPass::addDynamicLegal(
512	    ConversionTarget &target, TritonTypeConverter &tritonTypeConverter) {
513	  target.addLegalDialect<func::FuncDialect, arith::ArithDialect,
514	                         math::MathDialect, linalg::LinalgDialect,
515	                         affine::AffineDialect, scf::SCFDialect,
516	                         cf::ControlFlowDialect, tensor::TensorDialect,
517	                         LLVM::LLVMDialect, bufferization::BufferizationDialect,
518	                         memref::MemRefDialect, annotation::AnnotationDialect,
519	                         hivm::HIVMDialect, hfusion::HFusionDialect>();
520	
521	  // add legal dialect on condition
522	  target.addLegalOp<ModuleOp>();
523	
524	  // decide which ops need conversion based on uses
525	  target.addDynamicallyLegalOp<mlir::UnrealizedConversionCastOp>(
526	      [](mlir::Operation *op) {
527	        if (op->use_empty()) {
528	          return false;
529	        } else {
530	          return true;
531	        }
532	      });
533	
534	  target.addDynamicallyLegalOp<triton::FuncOp>([&](triton::FuncOp op) {
535	    return tritonTypeConverter.isSignatureLegal(op.getFunctionType());
536	  });
537	
538	  // For CustomOp/CustomMacroOp, tt.ptr should be converted to memref.
539	  target.addDynamicallyLegalOp<hivm::CustomOp>([&](hivm::CustomOp op) {
540	    return isCustomOpOperandTypesLegal(op->getOperandTypes());
541	  });
542	  target.addDynamicallyLegalOp<hivm::CustomMacroOp>(
543	      [&](hivm::CustomMacroOp op) {
544	        return isCustomOpOperandTypesLegal(op->getOperandTypes());
545	      });
546	
547	  target.addDynamicallyLegalOp<arith::ConstantOp>([](arith::ConstantOp op) {
548	    auto res = op.getResult();
549	    if (!isa<RankedTensorType>(res.getType())) {
550	      return true;
551	    }
552	
553	    if (auto denseAttr = dyn_cast<DenseElementsAttr>(op.getValue())) {
554	      if (!denseAttr.isSplat() ||
555	          !isa<FloatType, IntegerType>(denseAttr.getElementType())) {
556	        return true;
557	      }
558	      if (res.hasOneUse() && isa<tensor::ReshapeOp>(*res.user_begin())) {
559	        return true;
560	      }
561	      return false;
562	    }
563	    return true;
564	  });
565	
566	  target.addDynamicallyLegalOp<scf::ForOp, scf::YieldOp>([](Operation *op) {
567	    return llvm::all_of(op->getOperandTypes(), [](Type t) {
568	      if (isa<triton::PointerType>(t)) {
569	        return false;
570	      }
571	      if (auto shapedType = dyn_cast<ShapedType>(t)) {
572	        return shapedType.getElementType().isIntOrFloat();
573	      }
574	      assert(t.isIntOrIndexOrFloat());
575	      return true;
576	    });
577	  });
578	
579	  target.addDynamicallyLegalDialect<arith::ArithDialect, math::MathDialect>(
580	      [this](Operation *op) {
581	        if (op->hasAttr("MetaUse")) {
582	          return false;
583	        }
584	
585	        if (isa<arith::ConstantOp>(op)) {
586	          return true;
587	        }
588	
589	        bool operateOnTensors =
590	            llvm::all_of(op->getOperandTypes(),
591	                         [](Type type) { return isa<RankedTensorType>(type); });
592	
593	        return this->namedOps || !operateOnTensors;
594	      });
595	}
