761	LogicalResult
762	TritonToLinalgPass::processDescriptorOperations(ModuleOp moduleOp) {
763	  // --- ConversionTarget: dynamic legality checks ---
764	  mlir::ConversionTarget target(getContext());
765	  target.addLegalDialect<mlir::tensor::TensorDialect>();
766	
767	  // Dialect-level dynamic legality: ops are legal if none of their
768	  // operands/results use TensorDescType.
769	  target.addDynamicallyLegalDialect<
770	      mlir::arith::ArithDialect, mlir::scf::SCFDialect, triton::TritonDialect>(
771	      [](mlir::Operation *op) {
772	        return !DescriptorConverter::hasATensorDescriptorType(
773	                   op->getOperandTypes()) &&
774	               !DescriptorConverter::hasATensorDescriptorType(
775	                   op->getResultTypes());
776	      });
777	  // Function signature legality: Triton FuncOp is legal if its inputs/outputs
778	  // contain no TensorDescType.
779	  target.addDynamicallyLegalOp<triton::FuncOp>([](triton::FuncOp funcOp) {
780	    return !DescriptorConverter::hasATensorDescriptorType(
781	               funcOp.getFunctionType().getInputs()) &&
782	           !DescriptorConverter::hasATensorDescriptorType(
783	               funcOp.getFunctionType().getResults());
784	  });
785	  target.addLegalOp<triton::MakeTensorDescOp>();
786	  target.addIllegalOp<triton::DescriptorLoadOp, triton::DescriptorStoreOp,
787	                      triton::DescriptorScatterOp, triton::DescriptorGatherOp,
788	                      triton::DescriptorReduceOp>();
789	
790	  // --- Patterns ---
791	  mlir::RewritePatternSet patterns(&getContext());
792	  patterns.add<DescriptorConverter::DescriptorLoadConverter>(
793	      patterns.getContext());
794	  patterns.add<DescriptorConverter::DescriptorStoreConverter>(
795	      patterns.getContext());
796	  patterns.add<DescriptorConverter::DescriptorScatterConverter>(
797	      patterns.getContext());
798	  patterns.add<DescriptorConverter::DescriptorGatherConverter>(
799	      patterns.getContext());
800	  patterns.add<DescriptorConverter::DescriptorReduceConverter>(
801	      patterns.getContext());
802	
803	  mlir::ConversionConfig config;
804	  config.buildMaterializations = true;
805	  if (failed(applyPartialConversion(moduleOp, target, std::move(patterns),
806	                                    config))) {
807	    moduleOp->emitError("failed to convert tensor descriptor operations");
808	    return failure();
809	  }
810	
811	  return success();
812	}
