814	LogicalResult
815	TritonToLinalgPass::processPtrBroadcastOperations(ModuleOp moduleOp) {
816	  // --- ConversionTarget: dynamic legality checks ---
817	  mlir::ConversionTarget target(getContext());
818	  target.addLegalOp<triton::SplatOp>();
819	  target.addLegalOp<triton::AddPtrOp>();
820	  target.addDynamicallyLegalOp<triton::BroadcastOp>([](triton::BroadcastOp op) {
821	    if (op->hasAttr("MetaUse")) {
822	      return true;
823	    }
824	    auto resultType = dyn_cast<RankedTensorType>(op.getType());
825	    HoistBroadcast::BroadcastHoister hoister(op);
826	    return !(isa<triton::PointerType>(resultType.getElementType()) &&
827	             hoister.canBroadcast());
828	  });
829	
830	  // --- Patterns ---
831	  mlir::RewritePatternSet patterns(&getContext());
832	  patterns.add<HoistBroadcast::BroadcastConverter>(patterns.getContext());
833	
834	  if (failed(applyPartialConversion(moduleOp, target, std::move(patterns)))) {
835	    moduleOp->emitError("failed to convert ptr broadcast operations");
836	    return failure();
837	  }
838	
839	  return success();
840	}
