842	LogicalResult
843	TritonToLinalgPass::processImplicitPermuteOperations(ModuleOp moduleOp) {
844	  mlir::RewritePatternSet patterns(&getContext());
845	  patterns.add<ImplicitPermute::LoadConverter>(patterns.getContext());
846	  patterns.add<ImplicitPermute::StoreConverter>(patterns.getContext());
847	  patterns.add<ImplicitPermute::AtomicRMWConverter>(patterns.getContext());
848	  patterns.add<ImplicitPermute::AtomicCASConverter>(patterns.getContext());
849	  patterns.add<CannonicalizerConverter::SplatCmpConverter>(
850	      patterns.getContext());
851	
852	  if (failed(applyPatternsGreedily(moduleOp, std::move(patterns)))) {
853	    LLVM_DEBUG({ llvm::dbgs() << "ImplicitPermute: rewrite MemOp failed\n"; });
854	  }
855	
856	  mlir::PassManager pm(&getContext(), moduleOp.getOperationName());
857	  pm.addPass(createCSEPass());
858	  pm.addPass(createCanonicalizerPass());
859	  return runPipeline(pm, getOperation());
860	}
861	
862	LogicalResult TritonToLinalgPass::processStridedLoadStoreRewriteOperations(
863	    ModuleOp moduleOp) {
864	  // The strided-axis rewrites below only apply in 950 SIMT mode. On other
865	  // targets we leave strided loads to the legacy strided DMA lowering.
866	  if (!(compileOn91095Flag && forceSimtTemplateFlag)) {
867	    return success();
868	  }
869	
870	  // coalesce adjacent strided axes into one  so that to convert discrete memory
871	  // asccess into continuous memory access .
872	  StridedAxisCoalescing::rewriteStridedAxisCoalesce(moduleOp);
873	
874	  // TileChunkCoalescing (default-on, lower priority): when the outermost
875	  // program-id axis is a pure tile index over a contiguous problem axis with a
876	  // small tile T, fold H adjacent tiles into one program so the per-tile
877	  // load/store become a single contiguous H*T DMA (H picked so the block is
878	  // >= 512B and within UB). Emits hacc.coalesce_factor = H and
879	  // hacc.coalesce_axis. Bails when the pattern / lane-safety do not hold, when
880	  // the kernel reads num_programs(axis) (the launcher changes it), or when
881	  // StridedAxisCoalescing above already claimed the coalesce factor.
882	  TileChunkCoalescing::rewriteTileChunkCoalesce(moduleOp);
883	
884	  mlir::RewritePatternSet patterns(&getContext());
885	  patterns.add<StridedLoadStoreRewrite::LoadConverter,
886	               StridedLoadStoreRewrite::StoreConverter>(patterns.getContext());
887	
888	  if (failed(applyPatternsGreedily(moduleOp, std::move(patterns)))) {
889	    LLVM_DEBUG({
890	      llvm::dbgs() << "StridedLoadStoreRewrite: pattern application failed\n";
891	    });
892	    return failure();
893	  }
894	
895	  // Mirror processImplicitPermuteOperations: clean up dead IR left behind by
896	  // PtrAnalysis when the pattern decided not to rewrite (e.g. stride==1 case
897	  // returns failure() but PtrAnalysis has already inserted helper ExtSI ops).
898	  // Without this, downstream passes may trip on stale uses.
899	  mlir::PassManager pm(&getContext(), moduleOp.getOperationName());
900	  pm.addPass(createCSEPass());
901	  pm.addPass(createCanonicalizerPass());
902	  return runPipeline(pm, getOperation());
903	}
904	
905	LogicalResult
906	TritonToLinalgPass::processLegalStrideOperations(ModuleOp moduleOp) {
907	  mlir::ConversionTarget target(getContext());
908	  target.addLegalOp<arith::ConstantOp>();
909	  target.addDynamicallyLegalOp<memref::ReinterpretCastOp>(
910	      [](memref::ReinterpretCastOp op) {
911	        return !LoadStoreConverter::ReinterpretCastStrideCanonicalizer::
912	            hasFixableZeroStride(op);
913	      });
914	
915	  mlir::RewritePatternSet patterns(&getContext());
916	  patterns.add<LoadStoreConverter::ReinterpretCastStrideCanonicalizer>(
917	      patterns.getContext());
918	
919	  if (failed(applyPartialConversion(moduleOp, target, std::move(patterns)))) {
920	    moduleOp->emitError(
921	        "failed to legalize reinterpret_cast dynamic stride(0) with size(1)");
922	    return failure();
923	  }
924	
925	  return success();
926	}
927	
928	void TritonToLinalgPass::runOnOperation() {
929	  compileOn91095Flag = this->compileOn91095;
930	
931	  auto moduleOp = getOperation();
932	
933	  // Check if the kernel contains tl.dot. Without tl.dot,
934	  // the kernel would be pure AIV kernel.
935	  bool existDot = false;
936	  moduleOp.walk([&](triton::DotOp dotOp) {
937	    existDot = true;
938	    return WalkResult::interrupt();
939	  });
940	  moduleOp.walk([&](triton::DotScaledOp dotScaledOp) {
941	    existDot = true;
942	    return WalkResult::interrupt();
943	  });
944	  existDotFlag = existDot;
945	
946	  // NOTE: existSIMTOp is intentionally computed AFTER
947	  // processStridedLoadStoreRewriteOperations below, because that step
948	  // materializes triton::ascend::IndirectLoadOp/IndirectStoreOp (which
949	  // isSIMTOp() counts). Walking here (before the rewrite) would miss them and
950	  // mislabel the kernel parallel_mode as "simd" instead of "mix_simd_simt";
951	  // then enable_simt would be false and the launch would not reserve
952	  // localMemorySize for the SIMT templates -> VEC UB out-of-bounds (error 341)
953	  // at runtime on mix-CV kernels.
954	  bool existSIMTOp = false;
955	
956	  // Execute tensor descriptor operations conversion
957	  if (failed(processDescriptorOperations(moduleOp))) {
958	    signalPassFailure();
959	  }
960	
961	  // Execute implicit permute
962	  if (failed(processImplicitPermuteOperations(moduleOp))) {
963	    LLVM_DEBUG(
964	        { llvm::dbgs() << "Failed to process implicit permute operations\n"; });
965	    signalPassFailure();
966	  }
967	
968	  // SIMT IndirectLoad fast-path rewrite (runs after ImplicitPermute so the
969	  // permuted access patterns have already been absorbed; this step only
970	  // catches non-permuted last-axis stride > 1 loads).
971	  if (failed(processStridedLoadStoreRewriteOperations(moduleOp))) {
972	    LLVM_DEBUG({
973	      llvm::dbgs() << "Failed to process indirect-load rewrite operations\n";
974	    });
975	    signalPassFailure();
976	  }
977	
978	  // Detect SIMT ops AFTER the indirect-load rewrite so the freshly materialized
979	  // IndirectLoadOp/IndirectStoreOp are counted (drives parallel_mode ->
980	  // "mix_simd_simt" -> enable_simt -> launch reserves localMemorySize).
981	  moduleOp.walk([&](Operation *op) {
982	    if (isSIMTOp(op)) {
983	      existSIMTOp = true;
984	      LLVM_DEBUG({
985	        auto &os = llvm::dbgs();
986	        os << "Found SIMT op in function: ";
987	        os << op->getName();
988	        os << "\n";
989	      });
990	      return WalkResult::interrupt();
991	    }
992	    return WalkResult::advance();
993	  });
994	
995	  // 0. Annotate Memory-Related Triton FuncOps with tensor_kind (used by
996	  // profiling).
997	  {
998	    PassManager pm(&getContext(), moduleOp.getOperationName());
999	    pm.addPass(triton::createMarkTensorKindPass());
1000	    if (failed(runPipeline(pm, moduleOp))) {
1001	      moduleOp->emitError("failed to run LoopCanonicalizerPass");
1002	      signalPassFailure();
1003	      return;
1004	    }
1005	  }
1006	
1007	  RewritePatternSet canonicalizerPatterns(&getContext());
1008	  // 1. Canonicalize load/store related patterns.
1009	  this->populateTritonToLinalgCanonicalizationPatterns(canonicalizerPatterns);
1010	  if (failed(
1011	          applyPatternsGreedily(moduleOp, std::move(canonicalizerPatterns)))) {
1012	    moduleOp->emitError("failed to apply Canonicalizer Patterns");
1013	    signalPassFailure();
1014	  }
1015	
1016	  // 2.1 Pre-clean dead control-flow before use analysis.
1017	  // This helps remove unreachable branches such as `scf.if %true` else-region,
1018	  // so runUseAnalysis won't walk dead ops with missing lattice states.
1019	  {
1020	    PassManager pm(&getContext(), moduleOp.getOperationName());
1021	    pm.addPass(createCSEPass());
1022	    pm.addPass(createCanonicalizerPass());
1023	    if (failed(runPipeline(pm, moduleOp))) {
1024	      moduleOp->emitError(
1025	          "failed to pre-clean dead control-flow before use analysis");
1026	      signalPassFailure();
1027	      return;
1028	    }
1029	  }
1030	
1031	  // 2. Perform use analysis on FuncOp.
1032	  moduleOp.walk([this](triton::FuncOp op) {
1033	    if (failed(runUseAnalysis(op))) {
1034	      signalPassFailure();
1035	    }
1036	  });
1037	
1038	  RewritePatternSet patterns(&getContext());
1039	  ConversionTarget target(getContext());
1040	  TritonTypeConverter tritonTypeConverter{};
1041	
1042	  // 3. Mark legal dialects and operations.
1043	  this->addDynamicLegal(target, tritonTypeConverter);
1044	
1045	  // 4. Mark ops that must be converted explicitly (e.g. tt.scan).
1046	  auto loopOpLegalFn = [](LoopLikeOpInterface op) {
1047	    return !op.getOperation()->hasAttr("UnhandledLoopOp");
1048	  };
1049	
1050	  target.addIllegalOp<triton::ScanOp>();
1051	  target.addIllegalOp<triton::MapElementwiseOp>();
1052	  target.addDynamicallyLegalOp<scf::ForOp>(loopOpLegalFn);
1053	  target.addDynamicallyLegalOp<scf::WhileOp>(loopOpLegalFn);
1054	
1055	  // 5. Register converters for all illegal Triton ops.
1056	  // Execute ptr broadcast operations conversion
1057	  if (failed(processPtrBroadcastOperations(moduleOp))) {
1058	    signalPassFailure();
1059	  }
1060	  this->populateTritonToLinalgConversionPatterns(tritonTypeConverter, patterns,
1061	                                                 LAUNCH_GRID_RANK);
1062	
1063	  // 6. Inject program id / number of programs arguments into each Triton kernel
1064	  // function.
1065	  for (auto func : getOperation().getOps<triton::FuncOp>()) {
1066	    addProgramInfo(func, globalKernel);
1067	  }
1068	
1069	  moduleOp.walk([this](LoopLikeOpInterface loopOp) {
1070	    auto *op = loopOp.getOperation();
1071	    if (!op->hasAttr("ExtractedLoadOrStore"))
1072	      op->setAttr("UnhandledLoopOp", UnitAttr::get(op->getContext()));
1073	
1074	    for (auto res : loopOp->getResults()) {
1075	      if (auto tensorType = dyn_cast<RankedTensorType>(res.getType());
1076	          tensorType &&
1077	          !isa<triton::PointerType>(tensorType.getElementType())) {
1078	        IRRewriter rewriter(op->getContext());
1079	        rewriter.setInsertionPointAfter(op);
1080	        auto newVal =
1081	            rewriter.create<tensor::CastOp>(op->getLoc(), res.getType(), res);
1082	        rewriter.replaceAllUsesExcept(res, newVal, newVal);
1083	      }
1084	    }
1085	  });
1086	
1087	  // 7. Convert ops.
1088	  if (failed(applyPartialConversion(moduleOp, target, std::move(patterns)))) {
1089	    moduleOp->emitError("failed to apply Conversion Patterns");
1090	    signalPassFailure();
1091	  }
1092	
1093	  // 7.1 Workaround: fold duplicated one-hot reconstruction emitted after
1094	  // ArgMax lowering. The issue is not in triton::ReduceOp semantics themselves;
1095	  // redundant value reconstruction is materialized later and can lower to
1096	  // incorrect code on Ascend, so this is fixed post-conversion on
1097	  // linalg::ReduceOp.
1098	  {
1099	    RewritePatternSet foldPatterns(&getContext());
1100	    TTOpConverters::populatePostConversionCanonicalizationPatterns(
1101	        foldPatterns);
1102	
1103	    if (failed(applyPatternsGreedily(moduleOp, std::move(foldPatterns)))) {
1104	      moduleOp->emitError("failed to fold one-hot gather after max_with_index");
1105	      signalPassFailure();
1106	      return;
1107	    }
1108	  }
1109	
1110	  // Execute legal stride operations conversion
1111	  if (failed(processLegalStrideOperations(moduleOp))) {
1112	    signalPassFailure();
1113	  }
1114	
1115	  // 8. Convert function prologue/epilogue.
1116	  moduleOp.walk([&](triton::FuncOp func) {
1117	    this->convertTTFunc(func, existDot, existSIMTOp);
1118	  });
1119	
1120	  rewriteDevicePrintOffsets(moduleOp);
1121	
1122	  // 9. Clean up dead code and simplify IR.
1123	  PassManager pm(&getContext(), moduleOp.getOperationName());
1124	  pm.addPass(createCSEPass());
1125	  pm.addPass(createCanonicalizerPass());
1126	  if (failed(runPipeline(pm, getOperation()))) {
1127	    signalPassFailure();
1128	  }
1129	
1130	  // Calculate size of PointerCastOp precisely
1131	  SmallVector<hivm::PointerCastOp> castOps;
1132	
1133	  moduleOp.walk([&](hivm::PointerCastOp op) { castOps.push_back(op); });
1134	
1135	  for (auto op : castOps) {
1136	    SmallVector<Operation *> userOps(op->getUsers().begin(),
1137	                                     op->getUsers().end());
1138	    IRRewriter rewriter(&getContext());
1139	    rewriter.setInsertionPointAfter(op);
1140	    Value addr = op.getAddrs()[0];
1141	    auto elementType =
1142	        cast<MemRefType>(op.getResult().getType()).getElementType();
1143	    Value elementTypeSize;
1144	    if (auto intType = dyn_cast<IntegerType>(elementType)) {
1145	      elementTypeSize = rewriter.create<arith::ConstantOp>(
1146	          op.getLoc(),
1147	          rewriter.getIntegerAttr(addr.getType(), intType.getWidth() / 8));
1148	    } else if (auto floatType = dyn_cast<FloatType>(elementType)) {
1149	      elementTypeSize = rewriter.create<arith::ConstantOp>(
1150	          op.getLoc(),
1151	          rewriter.getIntegerAttr(addr.getType(), floatType.getWidth() / 8));
1152	    } else {
1153	      llvm_unreachable("Cannot get memory size");
1154	    }
1155	
1156	    for (auto userOp : userOps) {
1157	      auto reinterpretCastOp = cast<memref::ReinterpretCastOp>(userOp);
1158	      auto sizes = reinterpretCastOp.getStaticSizes();
1159	      auto staticStrides = reinterpretCastOp.getStaticStrides();
1160	      auto strides = reinterpretCastOp.getStrides();
1161	      if (reinterpretCastOp.getStaticOffsets().size() != 1)
1162	        userOp->emitError("IntToPtrOp must converted to PointerCastOp of "
1163	                          "memref<?xdtype> type");
1164	      int64_t castOpSize = 0;
1165	      SmallVector<int64_t> dynamicSizes;
1166	      for (const auto &[size, stride] : llvm::zip_equal(sizes, staticStrides)) {
1167	        assert(!ShapedType::isDynamic(size));
1168	        if (ShapedType::isDynamic(stride))
1169	          dynamicSizes.push_back(size);
1170	        else
1171	          castOpSize = size * stride;
1172	      }
1173	      rewriter.setInsertionPoint(reinterpretCastOp);
1174	      Value dynamicSize = rewriter.create<arith::ConstantOp>(
1175	          op.getLoc(), rewriter.getIndexAttr(castOpSize));
1176	      for (const auto &[size, stride] :
1177	           llvm::zip_equal(dynamicSizes, strides)) {
1178	        Value axisSize = rewriter.create<arith::ConstantOp>(
1179	            op.getLoc(), rewriter.getIndexAttr(size));
1180	        axisSize =
1181	            rewriter.create<arith::MulIOp>(op.getLoc(), stride, axisSize);
1182	        dynamicSize =
1183	            rewriter.create<arith::AddIOp>(op.getLoc(), dynamicSize, axisSize);
1184	      }
1185	      Value offsetValue;
1186	      auto staticOffset = reinterpretCastOp.getStaticOffsets()[0];
1187	      if (ShapedType::isDynamic(staticOffset)) {
1188	        offsetValue = reinterpretCastOp.getOffsets()[0];
1189	        if (offsetValue.getType() != addr.getType())
1190	          offsetValue = rewriter.create<arith::IndexCastOp>(
1191	              op.getLoc(), addr.getType(), offsetValue);
1192	      } else {
1193	        offsetValue = rewriter.create<arith::ConstantOp>(
1194	            op.getLoc(), rewriter.getIntegerAttr(addr.getType(), staticOffset));
1195	      }
1196	      offsetValue = rewriter.create<arith::MulIOp>(op.getLoc(), offsetValue,
1197	                                                   elementTypeSize);
1198	      Value realAddr =
1199	          rewriter.create<arith::AddIOp>(op.getLoc(), addr, offsetValue);
1200	      auto memrefType = MemRefType::get({ShapedType::kDynamic}, elementType);
1201	      auto newCastOp = rewriter.create<hivm::PointerCastOp>(
1202	          op.getLoc(), memrefType, realAddr, dynamicSize);
1203	      auto markOp = rewriter.create<annotation::MarkOp>(op.getLoc(),
1204	                                                        newCastOp.getResult());
1205	      markOp->setAttr(hivm::AddressSpaceAttr::getMnemonic(),
1206	                      {hivm::AddressSpaceAttr::get(rewriter.getContext(),
1207	                                                   hivm::AddressSpace::GM)});
1208	      rewriter.replaceOpWithNewOp<memref::ReinterpretCastOp>(
1209	          reinterpretCastOp,
1210	          cast<MemRefType>(reinterpretCastOp.getResult().getType()), newCastOp,
1211	          ValueRange({}), reinterpretCastOp.getSizes(),
1212	          reinterpretCastOp.getStrides(), SmallVector<int64_t>({0}),
1213	          reinterpretCastOp.getStaticSizes(),
1214	          reinterpretCastOp.getStaticStrides());
1215	    }
1216	    rewriter.eraseOp(op);
1217	  }
1218	
1219	  // Try interleave optimization
1220	  llvm::DenseMap<BlockArgument, SmallVector<Operation *>> interleaveCandidate;
1221	  llvm::DenseMap<BlockArgument, SmallVector<Operation *>>
1222	      interleaveCandidateWithMask;
1223	  moduleOp.walk([&](bufferization::MaterializeInDestinationOp materializeOp) {
1224	    if (auto reinterpretCastOp =
1225	            materializeOp.getDest()
1226	                .getDefiningOp<memref::ReinterpretCastOp>()) {
1227	      if (llvm::isa<BlockArgument>(reinterpretCastOp.getSource()) &&
1228	          reinterpretCastOp.getStaticStrides().back() == 2) {
1229	        interleaveCandidate[llvm::cast<BlockArgument>(
1230	                                reinterpretCastOp.getSource())]
1231	            .push_back(materializeOp);
1232	      }
1233	    }
1234	
1235	    // Difference is that converted op chain of store with mask has
1236	    // `memref::SubViewOp`
1237	    if (auto subviewOp =
1238	            materializeOp.getDest().getDefiningOp<memref::SubViewOp>()) {
1239	      if (!llvm::isa<tensor::ExtractSliceOp>(
1240	              materializeOp.getSource().getDefiningOp()))
1241	        return WalkResult::advance();
1242	
1243	      if (auto reinterpretCastOp =
1244	              subviewOp.getSource()
1245	                  .getDefiningOp<memref::ReinterpretCastOp>()) {
1246	        if (llvm::isa<BlockArgument>(reinterpretCastOp.getSource()) &&
1247	            reinterpretCastOp.getStaticStrides().back() == 2) {
1248	          interleaveCandidateWithMask[llvm::cast<BlockArgument>(
1249	                                          reinterpretCastOp.getSource())]
1250	              .push_back(materializeOp);
1251	        }
1252	      }
1253	    }
1254	
1255	    return WalkResult::advance();
1256	  });
1257	
1258	  for (auto [blockArg, materializeVec] : interleaveCandidate) {
1259	    // Just enable optimization where exists double materializeOp with same
1260	    // block argument destination.
1261	    if (materializeVec.size() != 2)
1262	      continue;
1263	    auto result = InterleaveStatusOptimization(materializeVec);
1264	  }
1265	
1266	  for (auto [blockArg, materializeVec] : interleaveCandidateWithMask) {
1267	    if (materializeVec.size() != 2)
1268	      continue;
1269	    auto result = InterleaveStatusWithMaskOptimization(materializeVec);
1270	  }
1271	
1272	  // Force to add an argument at the beginning of function arguments, which
1273	  // represents stub arg for workspace. Default type is memref<?xi8>
1274	  for (auto func : getOperation().getOps<func::FuncOp>()) {
1275	    if (!func->hasAttr("global_kernel"))
1276	      continue;
1277	
1278	    auto context = func.getContext();
1279	    constexpr int64_t syncBlockLockArgIdx = 0;
1280	    NamedAttribute syncBlockLockArgAttr(
1281	        StringAttr::get(context, "syncBlockLock"), UnitAttr::get(context));
1282	    MemRefType syncBlockLockArgType =
1283	        MemRefType::get(SmallVector<int64_t>(1, ShapedType::kDynamic),
1284	                        IntegerType::get(context, 8));
1285	    llvm::LogicalResult syncBlockLockArg =
1286	        func.insertArgument(syncBlockLockArgIdx,      // argIndex
1287	                            syncBlockLockArgType,     // argType
1288	                            nullptr, func->getLoc()); // dicAttr
1289	    func->setAttr("SyncBlockLockArgIdx",
1290	                  IntegerAttr::get(IntegerType::get(&getContext(), 64),
1291	                                   0)); // 64: 64位整型
1292	
1293	    constexpr int64_t workspaceArgIdx = 1;
1294	    MemRefType workspaceArgType =
1295	        MemRefType::get(SmallVector<int64_t>(1, ShapedType::kDynamic),
1296	                        IntegerType::get(context, 8));
1297	    NamedAttribute workspaceArgAttr(StringAttr::get(context, "workspace"),
1298	                                    UnitAttr::get(context));
1299	
1300	    llvm::LogicalResult workspaceArg =
1301	        func.insertArgument(/*argIndex*/ workspaceArgIdx,
1302	                            /*argType*/ workspaceArgType,
1303	                            /*dicAttr*/ nullptr, func->getLoc());
1304	    func->setAttr("WorkspaceArgIdx",
1305	                  IntegerAttr::get(IntegerType::get(&getContext(), 64),
1306	                                   1)); // 64: 64位整型
1307	  }
1308	
1309	  // Fix the Location info
1310	  moduleOp.walk([&](Operation *op) {
1311	    auto loc = op->getLoc();
1312	    if (isa<UnknownLoc>(loc)) {
1313	      llvm::SmallPtrSet<Operation *, 16> stopOps;
1314	      traverseForwardUpdateUserChainIf(
1315	          op,
1316	          /*conditionFn*/
1317	          [](Operation *curOp) { return false; },
1318	          /*stopFn*/
1319	          [](Operation *curOp) { return !isa<UnknownLoc>(curOp->getLoc()); },
1320	          /*actionFn*/
1321	          nullptr, stopOps);
1322	      if (stopOps.empty()) {
1323	        op->emitWarning() << *op << " and its users all have no location!";
1324	      } else {
1325	        Operation *goodOp = *stopOps.begin();
1326	        op->setLoc(goodOp->getLoc());
1327	      }
1328	    }
1329	    return WalkResult::advance();
1330	  });
1331	}
