1333	std::unique_ptr<OperationPass<ModuleOp>> triton::createTritonToLinalgPass(
1334	    bool globalKernel, bool namedOps, bool enableNd2nzOnVector,
1335	    bool enableSelectAnalysis, bool compileOn91095) {
1336	  return std::make_unique<TritonToLinalgPass>(
1337	      globalKernel, namedOps, enableNd2nzOnVector, enableSelectAnalysis,
1338	      compileOn91095);
1339	}
