105	/// @brief Check whether the triton::LoadOp has been modified to the specified
106	/// state by the AddPtrConverter.
107	/// @param op The triton::LoadOp operation to be checked.
108	/// @return Return success if the operation conforms to the specified state;
109	/// otherwise, return failure.
110	LogicalResult
111	LoadConverter::checkModifiedByAddPtrConverter(triton::LoadOp &op) const {
112	  if (!isa<scf::ForOp>(op->getParentOp())) {
113	    return failure();
114	  }
115	  if (!op->hasAttr("IndirectLoad")) {
116	    return failure();
117	  }
118	  auto ptrOp = op.getPtr().getDefiningOp();
119	  auto ptrBlock = ptrOp->getBlock();
120	  auto opBlock = op->getBlock();
121	  if (ptrBlock == opBlock) {
122	    return failure();
123	  }
124	
125	  return success();
126	}
