128	void LoadConverter::propagateWasBoolToInt8Attr(
129	    Operation *srcLoadOp, Operation *dstOp, PatternRewriter &rewriter) const {
130	  const std::string WasBoolToInt8TAG = "was_bool_to_int8";
131	  if (!srcLoadOp || !dstOp)
132	    return;
133	  if (srcLoadOp->hasAttr(WasBoolToInt8TAG)) {
134	    dstOp->setAttr(WasBoolToInt8TAG, rewriter.getBoolAttr(true));
135	  }
136	}
