138	/// @brief Continue to modify the triton::LoadOp from the state modified by the
139	/// AddPtrConverter.
140	/// @param op The triton::LoadOp operation to be processed.
141	/// @param adaptor The adaptor for the operation, used to obtain operands.
142	/// @param rewriter The pattern rewriter used to rewrite the operation.
143	/// @return Return success if the operation is successful; otherwise, return
144	/// failure.
145	LogicalResult LoadConverter::continueModifyFromAddPtrConverter(
146	    triton::LoadOp &op, OpAdaptor adaptor,
147	    ConversionPatternRewriter &rewriter) const {
148	  auto loc = op.getLoc();
149	  auto forOp = op->getParentOfType<scf::ForOp>();
150	  Operation *firstOp = &forOp.getBody()->front();
151	  auto extractOp = cast<tensor::ExtractOp>(firstOp);
152	  auto ivs = extractOp.getIndices();
153	  // Single iterArg which is inserted by AddPtrConverter.
154	  auto iterArg = forOp.getRegionIterArg(0);
155	  auto ptr = adaptor.getPtr();
156	
157	  rewriter.setInsertionPointAfter(op);
158	  Value castVal = ptr.getDefiningOp<memref::ReinterpretCastOp>();
159	  Value idxZero =
160	      rewriter.create<arith::ConstantOp>(loc, rewriter.getIndexAttr(0));
161	  Value loadVal =
162	      rewriter.create<memref::LoadOp>(loc, castVal, ValueRange{idxZero});
163	  propagateWasBoolToInt8Attr(op.getOperation(), loadVal.getDefiningOp(),
164	                             rewriter);
165	  Value insertedVal =
166	      rewriter.create<tensor::InsertOp>(loc, loadVal, iterArg, ValueRange{ivs});
167	  // a yield op is already created by AddPtrConverter.
168	  // so we need to replace it with a new yield op.
169	  Operation *terminator = forOp.getBody()->getTerminator();
170	  scf::YieldOp oldYieldOp = cast<scf::YieldOp>(terminator);
171	  auto yieldOp = rewriter.create<scf::YieldOp>(loc, ValueRange{insertedVal});
172	  rewriter.replaceOp(oldYieldOp, yieldOp);
173	  // Now the scf.for is complete, we can replace tt.load with it.
174	  auto rank = cast<ShapedType>(op.getResult().getType()).getShape().size();
175	  Operation *rootForOp = op;
176	  while (rank != 0) {
177	    rank--;
178	    rootForOp = rootForOp->getParentOfType<scf::ForOp>();
179	  }
180	  rewriter.replaceOp(op, rootForOp);
181	  LLVM_DEBUG({ llvm::dbgs() << *getModuleOpFromOperation(rootForOp) << "\n"; });
182	  return success();
183	}
184	
185	void LoadConverter::fillTensorWithOtherForMaskScenario(
186	    Value other, Value localMem, ArrayRef<OpFoldResult> maskDim,
187	    ConversionPatternRewriter &rewriter) const {
188	  auto loc = localMem.getLoc();
189	  MemRefType originalType = cast<MemRefType>(localMem.getType());
190	  assert(originalType.hasStaticShape() && "only support static shape");
191	  assert(originalType.getRank() == maskDim.size() &&
192	         "shape and mask must have same rank");
193	
194	  auto fillFlag =
195	      rewriter.create<arith::ConstantOp>(loc, rewriter.getBoolAttr(false))
196	          .getResult();
197	
198	  for (size_t i = 0; i < originalType.getShape().size(); ++i) {
199	    // Use dynamic value to judge whether overstep boundary
200	    auto shapeVal = rewriter.create<arith::ConstantOp>(
201	        loc, rewriter.getIndexAttr(originalType.getDimSize(i)));
202	
203	    Value maskDimVal;
204	    if (isa<Attribute>(maskDim[i]))
205	      maskDimVal = rewriter.create<arith::ConstantOp>(
206	          loc, cast<IntegerAttr>(cast<Attribute>(maskDim[i])));
207	    else
208	      maskDimVal = cast<Value>(maskDim[i]);
209	
210	    auto curCmp = rewriter.create<arith::CmpIOp>(loc, arith::CmpIPredicate::slt,
211	                                                 maskDimVal, shapeVal);
212	
213	    fillFlag = rewriter.create<arith::OrIOp>(loc, fillFlag, curCmp.getResult())
214	                   .getResult();
215	  }
216	  auto ifOp = rewriter.create<scf::IfOp>(loc, fillFlag);
217	  {
218	    OpBuilder::InsertionGuard guard(rewriter);
219	    rewriter.setInsertionPointToStart(&ifOp.getThenRegion().front());
220	    rewriter.create<linalg::FillOp>(loc, ValueRange{other},
221	                                    ValueRange{localMem});
222	  }
223	  ifOp->setAttr(rewriter.getStringAttr("hivm.unlikely_condition"),
224	                UnitAttr::get(rewriter.getContext()));
225	}
226	
227	LoadConverter::LoadConverter(MLIRContext *context)
228	    : OpConversionPattern<triton::LoadOp>(context) {}
229	
230	LogicalResult
231	LoadConverter::matchAndRewrite(triton::LoadOp op, OpAdaptor adaptor,
232	                               ConversionPatternRewriter &rewriter) const {
233	
234	  // Check if tt.load is modified by AddPtrConverter to a specified state.
235	  if (checkModifiedByAddPtrConverter(op).succeeded()) {
236	    return continueModifyFromAddPtrConverter(op, adaptor, rewriter);
237	  }
238	
239	  auto ptr = adaptor.getPtr();
240	  auto mask = op.getMask();
241	  auto other = op.getOther();
242	  auto loc = op.getLoc();
243	
244	  // handling scalar
245	  if (!isa<ShapedType>(op.getResult().getType())) {
246	    auto scalarMemref =
247	        BlockDataParser::getScalarMemRef(op.getPtr(), ptr, loc, rewriter);
248	    auto resTy = op.getResult().getType();
249	    auto idxZero =
250	        rewriter.create<arith::ConstantOp>(loc, rewriter.getIndexAttr(0));
251	    auto loadedValue = rewriter
252	                           .create<memref::LoadOp>(loc, resTy, scalarMemref,
253	                                                   idxZero.getResult())
254	                           .getResult();
255	    propagateWasBoolToInt8Attr(op.getOperation(), loadedValue.getDefiningOp(),
256	                               rewriter);
257	    if (mask && other) {
258	      mask = rewriter.create<triton::SplatOp>(
259	          loc, RankedTensorType::get({1}, mask.getType()), mask);
260	      loadedValue = rewriter.create<triton::SplatOp>(
261	          loc, RankedTensorType::get({1}, loadedValue.getType()), loadedValue);
262	      other = rewriter.create<triton::SplatOp>(
263	          loc, RankedTensorType::get({1}, other.getType()), other);
264	      loadedValue =
265	          rewriter.create<arith::SelectOp>(loc, mask, loadedValue, other);
266	      rewriter.replaceOpWithNewOp<tensor::ExtractOp>(op, loadedValue,
267	                                                     ValueRange({idxZero}));
268	    } else {
269	      rewriter.replaceOp(op, loadedValue);
270	    }
271	    return success();
272	  }
273	
274	  int64_t lastStride = -1;
275	  if (isa<BlockArgument>(ptr)) {
276	    auto u = ptr;
277	    while (auto blkArg = dyn_cast<BlockArgument>(u)) {
278	      if (auto forOp = dyn_cast<scf::ForOp>(blkArg.getOwner()->getParentOp())) {
279	        auto prt = forOp->getOperand(3 + blkArg.getArgNumber() - 1);
280	        u = prt;
281	      } else {
282	        u = nullptr;
283	        break;
284	      }
285	    }
286	    if (u && isa<memref::ReinterpretCastOp>(u.getDefiningOp())) {
287	      auto ret = mlir::ConverterUtils::getLastStrideOfReinterpretCastOp(
288	          dyn_cast<memref::ReinterpretCastOp>(u.getDefiningOp()));
289	      if (ret.has_value())
290	        lastStride = *ret;
291	    }
292	  }
293	
294	  // handling no mask
295	  auto memRefType = dyn_cast<MemRefType>(ptr.getType());
296	  if (!memRefType) {
297	    return rewriter.notifyMatchFailure(
298	        op, "LoadOp expects a memref, not a memref of pointers");
299	  }
300	  if (!op->hasAttr(ConverterUtils::GeneratedByMakeTensorPtrTAG)) {
301	    auto memrefOp = dyn_cast<memref::ReinterpretCastOp>(ptr.getDefiningOp());
302	    auto ret = mlir::ConverterUtils::getLastStrideOfReinterpretCastOp(memrefOp);
303	    if (ret.has_value())
304	      lastStride = *ret;
305	  }
306	  bool mayImplicitTransposeWithLastAxis =
307	      (existDotFlag) &&
308	      (!op->hasAttr(ConverterUtils::GeneratedByMakeTensorPtrTAG)) &&
309	      (lastStride != 1 &&
310	       mlir::ConverterUtils::isaPermutedMemRefType(memRefType));
311	  auto memRefShape = memRefType.getShape();
312	  auto memRefElementType = memRefType.getElementType();
313	
314	  Value allocOp;
315	  Value allocOpTmp;
316	  if (op->hasAttr(ConverterUtils::discreteAttrName)) {
317	    Operation *loop = op->getParentOp();
318	    int extractedLoopCount = 1;
319	    for (auto parentOp = loop->getParentOp();
320	         parentOp->hasAttr("ExtractedLoadOrStore");
321	         parentOp = parentOp->getParentOp()) {
322	      loop = parentOp;
323	      extractedLoopCount++;
324	    }
325	    rewriter.setInsertionPoint(loop);
326	    auto loopOp = cast<scf::ForOp>(loop);
327	    auto fullMemRefShape =
328	        cast<RankedTensorType>(loopOp.getInitArgs()[0].getType()).getShape();
329	    auto fullMemRefType = MemRefType::get(fullMemRefShape, memRefElementType);
330	    bool isIndexSelectScenario =
331	        (extractedLoopCount == 1) && (fullMemRefShape.size() > 1u);
332	    if (isIndexSelectScenario)
333	      loopOp->setAttr("hivm.parallel_loop", rewriter.getUnitAttr());
334	    allocOp = rewriter.create<memref::AllocOp>(loc, fullMemRefType);
335	    allocOpTmp = allocOp;
336	    rewriter.setInsertionPointAfter(loop);
337	    auto toTensorOp = rewriter.create<bufferization::ToTensorOp>(
338	        loc, RankedTensorType::get(fullMemRefShape, memRefElementType), allocOp,
339	        true, true);
340	    rewriter.replaceAllUsesWith(loopOp->getResult(0), toTensorOp->getResult(0));
341	    tensor::InsertSliceOp insertSliceOp = nullptr;
342	    for (auto *user : op->getUsers()) {
343	      if (auto targetOp = dyn_cast<tensor::InsertSliceOp>(user)) {
344	        insertSliceOp = targetOp;
345	        break;
346	      }
347	    }
348	    auto offsets = insertSliceOp.getMixedOffsets();
349	    auto sizes = insertSliceOp.getMixedSizes();
350	    auto strides = insertSliceOp.getMixedStrides();
351	    auto allocType = memref::SubViewOp::inferResultType(fullMemRefType, offsets,
352	                                                        sizes, strides);
353	    rewriter.setInsertionPoint(op);
354	    allocOp = rewriter.create<memref::SubViewOp>(
355	        loc, cast<MemRefType>(allocType), allocOp, offsets, sizes, strides);
356	    rewriter.replaceAllUsesExcept(insertSliceOp.getResult(),
357	                                  insertSliceOp.getDest(), insertSliceOp);
358	    rewriter.eraseOp(insertSliceOp);
359	  } else {
360	    allocOp = rewriter.create<memref::AllocOp>(
361	        loc, MemRefType::get(memRefShape, memRefElementType));
362	  }
363	
364	  auto tensorType = RankedTensorType::get(memRefShape, memRefElementType);
365	  // boundary check
366	  auto boundaryCheck = op.getBoundaryCheck();
367	  if (!boundaryCheck.empty()) {
368	    auto makeTensorPtrOp = op.getPtr().getDefiningOp<triton::MakeTensorPtrOp>();
369	    auto boundarySizes = mlir::ConverterUtils::getBoundarySizes(
370	        boundaryCheck, /*remapped*/ ptr, loc, rewriter);
371	    // handle the padding
372	    auto padding = op.getPadding();
373	    SmallVector<OpFoldResult> srcOffsets(boundarySizes.size(),
374	                                         rewriter.getIndexAttr(0));
375	    SmallVector<OpFoldResult> dstOffsets;
376	    if (makeTensorPtrOp) {
377	      auto zeroVal = rewriter.createOrFold<arith::ConstantOp>(
378	          loc, rewriter.getI32IntegerAttr(0));
379	      for (auto [idx, offVal] : llvm::enumerate(makeTensorPtrOp.getOffsets())) {
380	        if (llvm::find(boundaryCheck, idx) == boundaryCheck.end()) {
381	          dstOffsets.push_back(srcOffsets[idx]);
382	          continue;
383	        }
384	        Value offset =
385	            rewriter.createOrFold<arith::SubIOp>(loc, zeroVal, offVal);
386	        Value size =
387	            getValueOrCreateConstantIndexOp(rewriter, loc, boundarySizes[idx]);
388	        offset = rewriter.createOrFold<arith::MaxSIOp>(loc, offset, zeroVal);
389	        offset = rewriter.createOrFold<arith::IndexCastOp>(
390	            loc, rewriter.getIndexType(), offset);
391	        OpFoldResult ofr;
392	        if (auto constOp = offset.getDefiningOp<arith::ConstantOp>()) {
393	          ofr = constOp.getValue();
394	        } else {
395	          ofr = offset;
396	        }
397	        ofr = minOpFoldResult(ofr, size, loc, rewriter);
398	        boundarySizes[idx] = subOpFoldResult(size, ofr, loc, rewriter);
399	        dstOffsets.push_back(ofr);
400	      }
401	    } else {
402	      dstOffsets = srcOffsets;
403	    }
404	    if (padding.has_value()) {
405	      TypedAttr padAttr = rewriter.getZeroAttr(memRefElementType);
406	      // triton already ensure only NAN and ZERO are passed in
407	      if (padding.value() == triton::PaddingOption::PAD_NAN) {
408	        // FIXME: Why NaN requires elemTy to be non-int or non-index?
409	        assert(!memRefElementType.isIntOrIndex());
410	        auto apNaN = llvm::APFloat::getNaN(
411	            cast<FloatAttr>(padAttr).getValue().getSemantics());
412	        padAttr = rewriter.getFloatAttr(memRefElementType, apNaN);
413	      }
414	      auto padVal = rewriter.create<arith::ConstantOp>(loc, padAttr);
415	
416	      fillTensorWithOtherForMaskScenario(padVal, allocOp, boundarySizes,
417	                                         rewriter);
418	    }
419	    auto srcSubView = mlir::ConverterUtils::makeSubViewOp(
420	        ptr, srcOffsets, boundarySizes, loc, rewriter);
421	    auto dstSubview = mlir::ConverterUtils::makeSubViewOp(
422	        allocOp, dstOffsets, boundarySizes, loc, rewriter);
423	    auto copyOp = rewriter.create<memref::CopyOp>(loc, srcSubView, dstSubview);
424	    propagateWasBoolToInt8Attr(op.getOperation(), copyOp.getOperation(),
425	                               rewriter);
426	    if (mayImplicitTransposeWithLastAxis) {
427	      auto markOp = rewriter.create<annotation::MarkOp>(loc, dstSubview);
428	      markOp->setAttr(MayImplicitTransposeWithLastAxisTAG,
429	                      UnitAttr::get(rewriter.getContext()));
430	    }
431	    return this->toTensorAndReplace(op, tensorType, allocOp,
432	                                    mayImplicitTransposeWithLastAxis, loc,
433	                                    rewriter);
434	  }
435	
436	  if (!mask) {
437	    assert(!other && "can not input 'other' when 'mask' is not set");
438	    if (auto unrealizedCastOp =
439	            ptr.getDefiningOp<UnrealizedConversionCastOp>()) {
440	      // TODO : not support handle  associate with "module"
441	      // hint : can be handled in Linearize
442	      op->emitError("meeting unexpected UCC in LoadConverter!");
443	      return failure();
444	    } else {
445	      // If last dimension stride equals 2, try deinterleave optimization.
446	      auto [ptrStrides, ptrOffsets] = memRefType.getStridesAndOffset();
447	      if (ptrStrides.back() == 2 && (memRefShape.back() % 2 == 0) &&
448	          mlir::triton::DeinterleaveStatusOptimization(op, adaptor, rewriter)
449	              .succeeded()) {
450	        return success();
451	      }
452	      auto copyOp = rewriter.create<memref::CopyOp>(loc, ptr, allocOp);
453	      propagateWasBoolToInt8Attr(op.getOperation(), copyOp.getOperation(),
454	                                 rewriter);
455	      if (mayImplicitTransposeWithLastAxis &&
456	          allocOp.getDefiningOp<memref::AllocOp>()) {
457	        auto markOp = rewriter.create<annotation::MarkOp>(loc, allocOp);
458	        markOp->setAttr(MayImplicitTransposeWithLastAxisTAG,
459	                        UnitAttr::get(rewriter.getContext()));
460	      } else if (mayImplicitTransposeWithLastAxis &&
461	                 allocOp.getDefiningOp<memref::SubViewOp>()) {
462	        auto markOp = rewriter.create<annotation::MarkOp>(loc, allocOpTmp);
463	        markOp->setAttr(MayImplicitTransposeWithLastAxisTAG,
464	                        UnitAttr::get(rewriter.getContext()));
465	      }
466	    }
467	
468	    return this->toTensorAndReplace(op, tensorType, allocOp,
469	                                    mayImplicitTransposeWithLastAxis, loc,
470	                                    rewriter);
471	  }
472	
473	  MaskState mstate;
474	  auto isContMask = mstate.parse(mask, loc, rewriter);
475	  if (isContMask.failed()) {
476	    return rewriter.notifyMatchFailure(
477	        op, "can not lower uncontinuout masked loads");
478	  }
479	
480	  if (other) {
481	    auto scalarOther =
482	        mlir::ConverterUtils::getScalarValue(other, loc, rewriter);
483	    assert(
484	        scalarOther &&
485	        "other value used in masked load produced by unsupported instruction!");
486	
487	    fillTensorWithOtherForMaskScenario(scalarOther, allocOp, mstate.dims,
488	                                       rewriter);
489	  }
490	
491	  // To enable deinterleave optimization with mask load, mask state along last
492	  // dimension couldn't be split, which means `dims.back()` must be equal to
493	  // origin type last dimension constant size and `offsets.back()` must be 0.
494	  //
495	  // The basis is that last dimension range comparison would generate
496	  // unaccepted discontinuous mask.
497	  if (mstate.getRank() == memRefType.getRank() &&
498	      isConstantIntValue(mstate.offsets.back(), 0) &&
499	      isConstantIntValue(mstate.dims.back(), memRefType.getShape().back())) {
500	    auto [ptrStrides, ptrOffsets] = memRefType.getStridesAndOffset();
501	    if (ptrStrides.back() == 2 && (memRefType.getShape().back() % 2 == 0) &&
502	        DeinterleaveStatusWithMaskOptimization(op, adaptor, rewriter, mstate,
503	                                               allocOp)
504	            .succeeded()) {
505	      return success();
506	    }
507	  }
508	
509	  if (auto unrealizedCastOp = ptr.getDefiningOp<UnrealizedConversionCastOp>()) {
510	    // TODO : not support handle  associate with "module"
511	    // hint : can be handled in Linearize
512	    op->emitError("meeting unexpected UCC in LoadConverter!");
513	    return failure();
514	  } else {
515	    if (mstate.isMemrefSubviewValid(ptr, rewriter)) {
516	      memref::SubViewOp srcSubView = mstate.getSubview(ptr, loc, rewriter);
517	      memref::SubViewOp dstSubView = mstate.getSubview(allocOp, loc, rewriter);
518	      MemRefType dstSubViewType = mlir::cast<MemRefType>(dstSubView.getType());
519	
520	      auto [srcStrides, srcOffset] = dstSubViewType.getStridesAndOffset();
521	      MemRefType castType = MemRefType::get(
522	          dstSubViewType.getShape(), dstSubViewType.getElementType(),
523	          makeStridedLinearLayoutMap(srcStrides, srcOffset,
524	                                     rewriter.getContext()));
525	      auto castOp = rewriter.create<memref::CastOp>(loc, castType, dstSubView);
526	      auto copyOp = rewriter.create<memref::CopyOp>(loc, srcSubView, castOp);
527	      propagateWasBoolToInt8Attr(op.getOperation(), copyOp.getOperation(),
528	                                 rewriter);
529	    }
530	
531	    if (mayImplicitTransposeWithLastAxis &&
532	        allocOp.getDefiningOp<memref::AllocOp>()) {
533	      auto markOp = rewriter.create<annotation::MarkOp>(loc, allocOp);
534	      markOp->setAttr(MayImplicitTransposeWithLastAxisTAG,
535	                      UnitAttr::get(rewriter.getContext()));
536	    } else if (mayImplicitTransposeWithLastAxis &&
537	               allocOp.getDefiningOp<memref::SubViewOp>()) {
538	      auto markOp = rewriter.create<annotation::MarkOp>(loc, allocOpTmp);
539	      markOp->setAttr(MayImplicitTransposeWithLastAxisTAG,
540	                      UnitAttr::get(rewriter.getContext()));
541	    }
542	  }
543	  return this->toTensorAndReplace(
544	      op, tensorType, allocOp, mayImplicitTransposeWithLastAxis, loc, rewriter);
545	}
