547	AtomicRMWConverter::AtomicRMWConverter(MLIRContext *context)
548	    : OpConversionPattern<triton::AtomicRMWOp>(context) {}
549	
550	// lowering tt.atomicRMW to linalg.generic
551	// If atomic op's return value is used by other op as it's the old value stored
552	// at the ptrwe will use tt.load to get it
553	//
554	// example:
555	// input:
556	//  %return_value = tt.atomic_rmw fadd, acq_rel, gpu,
557	//     %output_memref, %input_tensor, %mask :
558	//             (tensor<256x!tt.ptr<f32>>, tensor<256xf32>, tensor<256xi1>)
559	//                       -> tensor<256xf32>
560	//
561	// output:
562	//  memref.copy %output_memref, %ub_buf : memref<?xf32> to memref<?xf32>
563	//  %17 = bufferization.to_tensor %alloc_3 restrict writable : memref<256xf32>
564	//  linalg.generic
565	//    {indexing_maps = [#map, #map, #map], iterator_types = ["parallel"]}
566	//    ins(%output_memref, %masked_input_memref : memref<?xf32>, memref<?xf32>)
567	//    outs(%subview_2 : memref<?xf32>)
568	//    attrs = {GenericAtomicRMW = "fadd", MemSemantic = "acq_rel",
569	//                                        MemSyncScope = "gpu"} {
570	//    ^bb0(%in: f32, %in_9: f32, %out: f32):
571	//      %25 = arith.addf %in, %in_9 : f32
572	//      linalg.yield %25 : f32
573	//    }
574	LogicalResult
575	AtomicRMWConverter::matchAndRewrite(triton::AtomicRMWOp op, OpAdaptor adaptor,
576	                                    ConversionPatternRewriter &rewriter) const {
577	  auto ptr = adaptor.getPtr();
578	  auto val = op.getVal();
579	  auto loc = op.getLoc();
580	  auto mask = op.getMask();
581	  auto rmwOp = op.getAtomicRmwOp();
582	  auto resType = dyn_cast<TensorType>(op.getResult().getType());
583	  auto ptrType = dyn_cast<MemRefType>(ptr.getType());
584	
585	  if (!resType)
586	    return rewriter.notifyMatchFailure(
587	        op, "atomicRMWConverter: scalar will be handled by "
588	            "ScalarAtomicRMWCanonicalizer");
589	  if (!ptrType)
590	    return rewriter.notifyMatchFailure(
591	        op, "AtomicRMWOp expects a memref, not a memref of pointers");
592	
593	  const std::map<RMWOp, hivm::AtomicKind> atomicKindMap = {
594	      {RMWOp::ADD, hivm::AtomicKind::ADD},
595	      {RMWOp::FADD, hivm::AtomicKind::ADD},
596	      {RMWOp::OR, hivm::AtomicKind::OR},
597	      {RMWOp::XOR, hivm::AtomicKind::XOR},
598	      {RMWOp::AND, hivm::AtomicKind::AND},
599	      {RMWOp::MIN, hivm::AtomicKind::MIN},
600	      {RMWOp::UMIN, hivm::AtomicKind::UMIN},
601	      {RMWOp::MAX, hivm::AtomicKind::MAX},
602	      {RMWOp::UMAX, hivm::AtomicKind::UMAX},
603	      {RMWOp::XCHG, hivm::AtomicKind::XCHG},
604	  };
605	  const std::map<RMWOp, hfusion::AtomicKind> hfusionAtomicKindMap = {
606	      {RMWOp::ADD, hfusion::AtomicKind::ADD},
607	      {RMWOp::FADD, hfusion::AtomicKind::ADD},
608	      {RMWOp::OR, hfusion::AtomicKind::OR},
609	      {RMWOp::XOR, hfusion::AtomicKind::XOR},
610	      {RMWOp::AND, hfusion::AtomicKind::AND},
611	      {RMWOp::MIN, hfusion::AtomicKind::MIN},
612	      {RMWOp::UMIN, hfusion::AtomicKind::UMIN},
613	      {RMWOp::MAX, hfusion::AtomicKind::MAX},
614	      {RMWOp::UMAX, hfusion::AtomicKind::UMAX},
615	      {RMWOp::XCHG, hfusion::AtomicKind::XCHG},
616	  };
617	  assert(atomicKindMap.find(rmwOp) != atomicKindMap.end());
618	  auto atomicKind =
619	      hivm::AtomicKindAttr::get(rewriter.getContext(), atomicKindMap.at(rmwOp));
620	  assert(hfusionAtomicKindMap.find(rmwOp) != hfusionAtomicKindMap.end());
621	  auto hfusionAtomicKind = hfusion::AtomicKindAttr::get(
622	      rewriter.getContext(), hfusionAtomicKindMap.at(rmwOp));
623	
624	  auto dstMemref = ptr;
625	  Value inputVal = val;
626	
627	  // Lazily materialize a memref view only when we truly need buffer
628	  // semantics (e.g., mask subview or XCHG lowering). Otherwise keep tensor
629	  // inputs to avoid redundant to_memref conversions before hivm.store.
630	  auto getInputMemref = [&]() -> Value {
631	    if (isa<MemRefType>(inputVal.getType()))
632	      return inputVal;
633	    return rewriter.create<bufferization::ToBufferOp>(loc, ptrType, inputVal);
634	  };
635	  auto inputMemref = getInputMemref();
636	  auto inputMemrefType = cast<MemRefType>(inputMemref.getType());
637	  auto elementType = inputMemrefType.getElementType();
638	  auto isHardwareSupported =
639	      (rmwOp == RMWOp::ADD || rmwOp == RMWOp::FADD || rmwOp == RMWOp::MAX ||
640	       rmwOp == RMWOp::MIN) &&
641	      (elementType.isF16() || elementType.isBF16() || elementType.isF32() ||
642	       elementType.isInteger(8) || elementType.isInteger(16) ||
643	       elementType.isInteger(32));
644	
645	  bool isDiscreteMask = false;
646	  if (mask) {
647	    auto constantMask = mask.getDefiningOp<arith::ConstantOp>();
648	    if (constantMask && !isConstantMaskTrue(mask)) {
649	      rewriter.eraseOp(op);
650	      return success();
651	    }
652	    MaskState mstate;
653	    isDiscreteMask = mstate.parse(mask, loc, rewriter).failed();
654	    if (!constantMask && !isDiscreteMask) {
655	      // For dstMemref (store output), use subview to maintain reference to
656	      // original memref. For inputVal (store input), use tensor.extract_slice
657	      // to keep tensor semantics.
658	      dstMemref = mstate.getSubview(ptr, loc, rewriter);
659	      if (isHardwareSupported) {
660	        auto inputTensorType = RankedTensorType::get(
661	            inputMemrefType.getShape(), inputMemrefType.getElementType());
662	        if (!isa<RankedTensorType>(inputVal.getType()))
663	          inputVal = rewriter.create<bufferization::ToTensorOp>(
664	              loc, inputTensorType, inputMemref, true, true);
665	        inputVal = mstate.getExtractSlice(inputVal, loc, rewriter);
666	      } else {
667	        inputMemref = mstate.getSubview(inputMemref, loc, rewriter);
668	      }
669	    }
670	  }
671	
672	  if (!op.getResult().use_empty()) {
673	    auto tensorType =
674	        RankedTensorType::get(ptrType.getShape(), ptrType.getElementType());
675	    auto alloc = rewriter.create<memref::AllocOp>(
676	        loc, MemRefType::get(ptrType.getShape(), ptrType.getElementType()));
677	    rewriter.create<memref::CopyOp>(loc, ptr, alloc);
678	    Value tensorToReplace = rewriter.create<bufferization::ToTensorOp>(
679	        loc, tensorType, alloc, true /* restrict */, true /* writable */);
680	    rewriter.replaceOp(op, tensorToReplace);
681	  }
682	
683	  if (isDiscreteMask) {
684	    if (rmwOp != RMWOp::XCHG) {
685	      return op.emitError(
686	          "Discrete mask is only expected for XCHG; other atomics "
687	          "should be lowered without discrete masks");
688	    }
689	    Value memrefMask = mask;
690	    if (auto maskTypeT = dyn_cast<TensorType>(mask.getType())) {
691	      MemRefType maskTypeM =
692	          MemRefType::get(maskTypeT.getShape(), maskTypeT.getElementType());
693	      memrefMask =
694	          rewriter.create<bufferization::ToBufferOp>(loc, maskTypeM, mask);
695	    }
696	    rewriter.create<hfusion::AtomicXchgOp>(op.getLoc(), TypeRange(),
697	                                           inputMemref, dstMemref, memrefMask);
698	  } else {
699	    if (isHardwareSupported)
700	      rewriter.create<hivm::StoreOp>(op.getLoc(), TypeRange{}, inputVal,
701	                                     dstMemref, atomicKind);
702	    else if (rmwOp == RMWOp::XCHG)
703	      rewriter.create<hfusion::AtomicXchgOp>(op.getLoc(), TypeRange(),
704	                                             inputMemref, dstMemref);
705	    else {
706	      if (rmwOp == RMWOp::OR || rmwOp == RMWOp::XOR || rmwOp == RMWOp::AND) {
707	        if (!elementType.isSignlessIntOrIndex()) {
708	          return op->emitOpError()
709	                 << "must be signless-integer-like, but got " << elementType;
710	        }
711	      }
712	      // Currently, for atomic kind and element type that is not supported by
713	      // the hardware, we use software to simulate the computation. However,
714	      // decompose now happens in both HFusion and HIVM, and is not consistent
715	      // for 910B and 91095. Therefore, we convert to different atomic/store ops
716	      // for now. This should be unified and refactored later.
717	      if (compileOn91095Flag) {
718	        rewriter.create<hfusion::StoreOp>(
719	            op.getLoc(), TypeRange{}, ValueRange{inputMemref},
720	            ValueRange{dstMemref}, hfusionAtomicKind,
721	            ArrayRef<NamedAttribute>{});
722	      } else {
723	        rewriter.create<hfusion::AtomicRMWOp>(op.getLoc(), TypeRange(),
724	                                              inputMemref, dstMemref,
725	                                              hfusionAtomicKind);
726	      }
727	    }
728	  }
729	
730	  if (op.getResult().use_empty()) {
731	    rewriter.eraseOp(op);
732	  }
733	  return success();
734	}
