736	LogicalResult
737	AtomicCASConverter::matchAndRewrite(triton::AtomicCASOp op, OpAdaptor adaptor,
738	                                    ConversionPatternRewriter &rewriter) const {
739	  // If the result of AtomicCASOp is not used, we don't need to load the old
740	  // data stored at the ptr
741	  auto ptr = adaptor.getPtr();
742	  auto cmp = op.getCmp();
743	  auto val = op.getVal();
744	  auto loc = op.getLoc();
745	
746	  auto resType = dyn_cast<TensorType>(op.getResult().getType());
747	  if (!resType) {
748	    return rewriter.notifyMatchFailure(
749	        op, "atomicCASConverter: scalar will be handled by "
750	            "ScalarAtomicCASCanonicalizer");
751	  }
752	
753	  // 1. Simple case where no mask is used.
754	  auto type = dyn_cast<MemRefType>(ptr.getType());
755	  if (!type) {
756	    // Seen when implicit broadcasting is done late in a chain of
757	    // operations. The workaround is to broadcast the pointers early in the
758	    // address calculation. A proper fix is complicated, but at least we can
759	    // provide a better error message.
760	    return rewriter.notifyMatchFailure(
761	        op, "AtomicCASOp expects a memref, not a memref of pointers");
762	  }
763	
764	  auto dstMemref = ptr;
765	  // Well, linalg structure op wouldn't support mixed tensor/buffer semantics
766	  // any more in latest LLVM(triton LLVM dependency has involed this), so we
767	  // need to convert tensor to buffer early.
768	  auto dstOriType = cast<MemRefType>(dstMemref.getType());
769	  MemRefType dstType =
770	      MemRefType::get(dstOriType.getShape(), dstOriType.getElementType());
771	  Value inputMemref =
772	      rewriter.create<bufferization::ToBufferOp>(loc, dstType, val);
773	
774	  Value cmpMemref =
775	      rewriter.create<bufferization::ToBufferOp>(loc, dstType, cmp);
776	
777	  // create element-wise map
778	  int64_t rank = type.getRank();
779	  SmallVector<AffineExpr> inputDims;
780	  auto context = rewriter.getContext();
781	
782	  for (int i = 0; i < rank; i++) {
783	    inputDims.push_back(getAffineDimExpr(i, context));
784	  }
785	
786	  SmallVector<AffineMap> indexingMaps;
787	  // As mask has been erased for now
788	  // the number of input must be 2
789	  // the input memref is also the output memref
790	  // Thus, there are a total of four inputs and outputs.
791	  // so here we have 4 map to create
792	  for (int i = 0; i < 4; i++) { // 4: 3 input and 1 output
793	    indexingMaps.push_back(AffineMap::get(rank, 0, inputDims, context));
794	  }
795	
796	  if (!op.getResult().use_empty()) {
797	    auto tensorType =
798	        RankedTensorType::get(type.getShape(), type.getElementType());
799	    auto alloc = rewriter.create<memref::AllocOp>(
800	        loc, MemRefType::get(type.getShape(), type.getElementType()));
801	
802	    // For the return value, don't need to care about mask for now
803	    // this op don't support other, so we best not fill it
804	    rewriter.create<memref::CopyOp>(loc, ptr, alloc);
805	    Value tensor = rewriter.create<bufferization::ToTensorOp>(
806	        loc, tensorType, alloc, true /* restrict */, true /* writable */);
807	    rewriter.replaceOp(op, tensor);
808	  }
809	
810	  auto linalgOp = rewriter.create<linalg::GenericOp>(
811	      loc, ValueRange{dstMemref, cmpMemref, inputMemref},
812	      mlir::ValueRange{dstMemref}, indexingMaps,
813	      mlir::ConverterUtils::getNParallelLoopsAttrs(rank),
814	      [&](OpBuilder &nestedBuilder, Location nestedLoc, ValueRange blockArgs) {
815	        Value lhs = blockArgs[0];
816	        Value rhs = blockArgs[1];
817	        Value setValue = blockArgs[2];
818	        Value cond;
819	        if (mlir::isa<mlir::FloatType>(lhs.getType())) {
820	          cond = nestedBuilder.create<arith::CmpFOp>(
821	              nestedLoc, arith::CmpFPredicate::UEQ, lhs, rhs);
822	        } else {
823	          cond = nestedBuilder.create<arith::CmpIOp>(
824	              nestedLoc, arith::CmpIPredicate::eq, lhs, rhs);
825	        }
826	        auto ifOp = nestedBuilder.create<scf::IfOp>(
827	            nestedLoc, TypeRange{setValue.getType()}, cond, true);
828	        {
829	          OpBuilder::InsertionGuard guard(nestedBuilder);
830	          nestedBuilder.setInsertionPointToEnd(&ifOp.getThenRegion().front());
831	          nestedBuilder.create<scf::YieldOp>(nestedLoc, setValue);
832	        }
833	        {
834	          OpBuilder::InsertionGuard guard(nestedBuilder);
835	          nestedBuilder.setInsertionPointToEnd(&ifOp.getElseRegion().front());
836	          nestedBuilder.create<scf::YieldOp>(nestedLoc, lhs);
837	        }
838	        nestedBuilder.setInsertionPointToEnd(nestedBuilder.getBlock());
839	        nestedBuilder.create<mlir::linalg::YieldOp>(nestedLoc,
840	                                                    ifOp.getResult(0));
841	      });
842	
843	  const StringRef genericAtomicRMW = "GenericAtomicRMW";
844	  const StringRef memSemantic = "MemSemantic";
845	  const StringRef memSyncScope = "MemSyncScope";
846	  auto attr = mlir::StringAttr::get(context, "cas");
847	
848	  linalgOp->setAttr(genericAtomicRMW, attr);
849	  linalgOp->setAttr(memSemantic,
850	                    rewriter.getStringAttr(stringifyEnum(op.getSem())));
851	  linalgOp->setAttr(memSyncScope,
852	                    rewriter.getStringAttr(stringifyEnum(op.getScope())));
853	
854	  linalgOp->setAttr("Software", rewriter.getUnitAttr());
855	
856	  // tt.atomicRMW op has two part of feature
857	  // 1. load the old data at the ptr
858	  // 2. atomically store the data on ub to the ptr
859	  //    at the same time it perform the action it has been assigned
860	  // So we lower this op to load + atomically store
861	  //
862	  // The first part is not necessary when the returned value of atomic op
863	  // is not used, it will be deleted cause it's meaningless
864	  // Here, we preemptively determine whether it will be used
865	  // and decide whether it is necessary to create the load process based on
866	  // this assessment.
867	  //
868	  // logic of handling is copied
869	  if (op.getResult().use_empty()) {
870	    rewriter.eraseOp(op);
871	  }
872	  return success();
873	}
