875	LogicalResult
876	ScalarStoreCanonicalizer::matchAndRewrite(triton::StoreOp op,
877	                                          PatternRewriter &rewriter) const {
878	  if (!op.getValue().getType().isIntOrIndexOrFloat()) {
879	    return rewriter.notifyMatchFailure(
880	        op, "ScalarStoreCanonicalizer handles scalar store scene!");
881	  }
882	  auto ptr = op.getPtr();
883	  auto mask = op.getMask();
884	  auto value = op.getValue();
885	  if (mask) {
886	    rewriter.replaceOpWithNewOp<scf::IfOp>(
887	        op, mask, [&](OpBuilder &b, Location loc) {
888	          b.create<triton::StoreOp>(loc, ptr, value, op.getCache(),
889	                                    op.getEvict());
890	          b.create<scf::YieldOp>(loc);
891	        });
892	    return success();
893	  }
894	
895	  auto ptrTy = RankedTensorType::get({(int64_t)1}, ptr.getType());
896	  auto ptrSplat = rewriter.create<triton::SplatOp>(op.getLoc(), ptrTy, ptr);
897	  auto valTy = RankedTensorType::get({(int64_t)1}, value.getType());
898	  auto valSplat = rewriter.create<triton::SplatOp>(op.getLoc(), valTy, value);
899	  auto newStoreOp = rewriter.create<triton::StoreOp>(
900	      op.getLoc(), ptrSplat, valSplat, op.getCache(), op.getEvict());
901	  rewriter.replaceOp(op, newStoreOp);
902	  return success();
903	}
