907	                                              PatternRewriter &rewriter) const {
908	  if (!op.getVal().getType().isIntOrIndexOrFloat()) {
909	    return rewriter.notifyMatchFailure(
910	        op, "ScalarAtomicRMWCanonicalizer handles scalar atomic rmw op scene!");
911	  }
912	
913	  auto ptr = op.getPtr();
914	  auto ptrTy = RankedTensorType::get({(int64_t)1}, ptr.getType());
915	  auto ptrSplat = rewriter.create<triton::SplatOp>(op.getLoc(), ptrTy, ptr);
916	  auto valTy = RankedTensorType::get({(int64_t)1}, op.getVal().getType());
917	  auto valSplat =
918	      rewriter.create<triton::SplatOp>(op.getLoc(), valTy, op.getVal());
919	  auto maskTy = RankedTensorType::get({(int64_t)1}, op.getMask().getType());
920	  auto maskSplat =
921	      rewriter.create<triton::SplatOp>(op.getLoc(), maskTy, op.getMask());
922	
923	  auto newAtomicOp = rewriter.create<triton::AtomicRMWOp>(
924	      op.getLoc(), valTy, op.getAtomicRmwOp(), ptrSplat, valSplat, maskSplat,
925	      op.getSem(), op.getScope());
926	  auto idxZero =
927	      rewriter.create<arith::ConstantOp>(op.getLoc(), rewriter.getIndexAttr(0));
928	  rewriter.replaceOpWithNewOp<tensor::ExtractOp>(op, newAtomicOp,
929	                                                 ValueRange({idxZero}));
930	  return success();
931	}
