962	// The atomic max op with float input will be devided into
963	// two atomic max ops with integer input
964	// One handles the part of the tensor greater than zero
965	// the other deals with the part less than zero
966	// It will lead to maskAnalysis failure
967	// So here we need to revert the procedures in semantics.py
968	// The triton IR is like
969	//
970	// %cst_0 = arith.constant dense<0.000000e+00> : tensor<1x256xf32>
971	// %1 = tt.bitcast %value : tensor<1x256xf32> -> tensor<1x256xi32>
972	// %2 = tt.bitcast %ptr : tensor<1x256x!tt.ptr<f32>> ->
973	// tensor<1x256x!tt.ptr<i32>> %3 = arith.cmpf oge, %1, %cst_0 %4 = arith.cmpf
974	// olt, %1, %cst_0 %5 = arith.andi %8, %3 %6 = tt.atomic_rmw max, acq_rel, gpu,
975	// %2, %1, %5 :
976	//    (tensor<1x256x!tt.ptr<i32>>, tensor<1x256xi32>, tensor<1x256xi1>) ->
977	//    tensor<1x256xi32>
978	// %7 = arith.andi %8, %4
979	// %8 = tt.atomic_rmw umin, acq_rel, gpu, %2, %1, %7 :
980	//    (tensor<1x256x!tt.ptr<i32>>, tensor<1x256xi32>, tensor<1x256xi1>) ->
981	//    tensor<1x256xi32>
982	//
983	// it's hard to handle and meaningless complicated for our device
984	// so we revert it to
985	// %0 = tt.atomic_rmw max, acq_rel, gpu, %23, %21, %8 :
986	//    (tensor<1x256x!tt.ptr<f32>>, tensor<1x256xf32>, tensor<1x256xi1>) ->
987	//    tensor<1x256xf32>
988	LogicalResult
989	AtomicMaxMinCanonicalizer::matchAndRewrite(triton::AtomicRMWOp op,
990	                                           PatternRewriter &rewriter) const {
991	  // Revert the op to its original form
992	  auto ptrBitcastOp = op.getPtr().getDefiningOp<triton::BitcastOp>();
993	  auto valueBitcastOp = op.getVal().getDefiningOp<triton::BitcastOp>();
994	  if (!ptrBitcastOp || !valueBitcastOp) {
995	    return failure();
996	  }
997	
998	  // We only need to handle the op when the element type is float
999	  auto elementType =
1000	      dyn_cast<TensorType>(valueBitcastOp.getSrc().getType()).getElementType();
1001	  if (!isa<FloatType>(elementType)) {
1002	    return failure();
1003	  }
1004	
1005	  auto rmwOp = op.getAtomicRmwOp();
1006	  // here we know that atomic UMAX/UMIN
1007	  // is created by special logic of triton right now
1008	  // so we can simply delete it
1009	  if (rmwOp == triton::RMWOp::UMAX || rmwOp == triton::RMWOp::UMIN) {
1010	    // if the return value of op is used, we can't simply erase it
1011	    if (op.getResult().use_empty()) {
1012	      rewriter.eraseOp(op);
1013	      return success();
1014	    }
1015	    return failure();
1016	  }
1017	
1018	  if (rmwOp != triton::RMWOp::MAX && rmwOp != triton::RMWOp::MIN) {
1019	    return failure();
1020	  }
1021	
1022	  // 1. Though semantic interpreter will generate full true tensor as original
1023	  // mask if atomicrmwOp don't have it, above float devision process will also
1024	  // generate positive and negative comparison mask, which will cause to fold
1025	  // true mask.
1026	  // 2. While if atomicrmwOp has original mask, there exists andiop between
1027	  // original mask and positive/negative comparison mask
1028	  //
1029	  // Here wanna extract original mask
1030	  Value originalMask = op.getMask();
1031	  if (auto andOp = originalMask.getDefiningOp<arith::AndIOp>())
1032	    // LHS is convention in semantic interpreter
1033	    originalMask = andOp.getLhs();
1034	  else if (auto cmpOp = originalMask.getDefiningOp<arith::CmpFOp>()) {
1035	    if (cmpOp.getPredicate() != mlir::arith::CmpFPredicate::OGE ||
1036	        !matchPattern(cmpOp.getRhs(),
1037	                      /*positive float zero matcher*/ m_PosZeroFloat()))
1038	      // Here recheck frontend interpreter generation in no manual mask state
1039	      return op->emitError("Illegal mask for atomicrmwOp of float type");
1040	    // Restore original true mask
1041	    originalMask = rewriter.create<arith::ConstantOp>(
1042	        op->getLoc(),
1043	        /*typed attr*/ DenseElementsAttr::get(
1044	            cast<ShapedType>(originalMask.getType()), true));
1045	  } else
1046	    return op->emitError("Illegal mask for atomicrmwOp of float type");
1047	
1048	  auto originAtomicOp = rewriter.create<triton::AtomicRMWOp>(
1049	      op.getLoc(), valueBitcastOp.getSrc().getType(), op.getAtomicRmwOp(),
1050	      ptrBitcastOp.getSrc(), valueBitcastOp.getSrc(), originalMask, op.getSem(),
1051	      op.getScope());
1052	
1053	  // if the return value of op is used
1054	  // we need to handle its usage
1055	  // In semantic.py, if the atomic Max/Min with float input is used
1056	  // It will use select + bitcast to get float value
1057	  // so here we need to revert it too
1058	  //
1059	  // For example:
1060	  // %0 = tt.atomic_rmw max, acq_rel, gpu, %gm, %input, %mask1 :
1061	  // (tensor<32x!tt.ptr<i32>>... %1 = tt.atomic_rmw umin, acq_rel, gpu, %gm,
1062	  // %input, %mask2 : (tensor<32x!tt.ptr<i32>>... %2 = arith.select
1063	  // %devidedMask, %0, %1 : tensor<32xi1>, tensor<32xi32> %3 = tt.bitcast %2 :
1064	  // tensor<32xi32> -> tensor<32xf32> tt.store %outputMemref, %3 :
1065	  // tensor<32x!tt.ptr<f32>>
1066	  //
1067	  // will be revert to:
1068	  // %0 = tt.atomic_rmw max, acq_rel, gpu, %gm, %input, %mask :
1069	  // (tensor<32x!tt.ptr<f32>>... tt.store %outputMemref, %0 :
1070	  // tensor<32x!tt.ptr<f32>>
1071	  //
1072	  if (!op.getResult().use_empty()) {
1073	    for (OpOperand &use : op->getUses()) {
1074	      auto selectOp = dyn_cast<arith::SelectOp>(use.getOwner());
1075	      if (!selectOp)
1076	        continue;
1077	
1078	      for (OpOperand &selectUse : selectOp->getUses()) {
1079	        if (auto bitcastOp =
1080	                dyn_cast<triton::BitcastOp>(selectUse.getOwner())) {
1081	          bitcastOp.getResult().replaceAllUsesWith(originAtomicOp);
1082	        }
1083	      }
1084	    }
1085	    rewriter.replaceOp(op, originAtomicOp);
1086	  } else {
1087	    rewriter.eraseOp(op);
1088	  }
1089	
1090	  return success();
1091	}
