1093	StoreConverter::StoreConverter(MLIRContext *context)
1094	    : OpConversionPattern<triton::StoreOp>(context) {}
1095	
1096	LogicalResult
1097	StoreConverter::matchAndRewrite(triton::StoreOp op, OpAdaptor adaptor,
1098	                                ConversionPatternRewriter &rewriter) const {
1099	
1100	  // triton store op basic
1101	  auto mask = op.getMask();
1102	  auto loc = op.getLoc();
1103	  auto ptr = adaptor.getPtr();
1104	  auto val = adaptor.getValue();
1105	
1106	  // 1. boundary size check
1107	  auto boundaryCheck = op.getBoundaryCheck();
1108	  if (!boundaryCheck.empty()) {
1109	    auto makeTensorPtrOp = op.getPtr().getDefiningOp<triton::MakeTensorPtrOp>();
1110	    auto boundarySizes = mlir::ConverterUtils::getBoundarySizes(
1111	        boundaryCheck, /*remapped*/ ptr, loc, rewriter);
1112	    SmallVector<OpFoldResult> srcOffsets;
1113	    SmallVector<OpFoldResult> dstOffsets(boundarySizes.size(),
1114	                                         rewriter.getIndexAttr(0));
1115	    if (makeTensorPtrOp) {
1116	      auto zeroVal = rewriter.createOrFold<arith::ConstantOp>(
1117	          loc, rewriter.getI32IntegerAttr(0));
1118	      for (auto [idx, offVal] : llvm::enumerate(makeTensorPtrOp.getOffsets())) {
1119	        if (llvm::find(boundaryCheck, idx) == boundaryCheck.end()) {
1120	          srcOffsets.push_back(dstOffsets[idx]);
1121	          continue;
1122	        }
1123	        Value offset =
1124	            rewriter.createOrFold<arith::SubIOp>(loc, zeroVal, offVal);
1125	        Value size =
1126	            getValueOrCreateConstantIndexOp(rewriter, loc, boundarySizes[idx]);
1127	        offset = rewriter.createOrFold<arith::MaxSIOp>(loc, offset, zeroVal);
1128	        offset = rewriter.createOrFold<arith::IndexCastOp>(
1129	            loc, rewriter.getIndexType(), offset);
1130	        OpFoldResult ofr;
1131	        if (auto constOp = offset.getDefiningOp<arith::ConstantOp>()) {
1132	          ofr = constOp.getValue();
1133	        } else {
1134	          ofr = offset;
1135	        }
1136	        ofr = minOpFoldResult(ofr, size, loc, rewriter);
1137	        boundarySizes[idx] = subOpFoldResult(size, ofr, loc, rewriter);
1138	        srcOffsets.push_back(ofr);
1139	      }
1140	    } else {
1141	      srcOffsets = dstOffsets;
1142	    }
1143	    auto srcSlice = mlir::ConverterUtils::makeExtractSliceOp(
1144	        val, srcOffsets, boundarySizes, loc, rewriter);
1145	    auto dstSubview = mlir::ConverterUtils::makeSubViewOp(
1146	        ptr, dstOffsets, boundarySizes, loc, rewriter);
1147	    auto storeOp = rewriter.create<bufferization::MaterializeInDestinationOp>(
1148	        loc, srcSlice, dstSubview);
1149	    storeOp.setWritable(true);
1150	    rewriter.eraseOp(op);
1151	    return success();
1152	  }
1153	
1154	  // 2. Simple load with no mask
1155	  if (!mask) {
1156	    auto storeOp = rewriter.create<bufferization::MaterializeInDestinationOp>(
1157	        loc, val, ptr);
1158	    storeOp.setWritable(true);
1159	    rewriter.eraseOp(op);
1160	    return success();
1161	  }
1162	
1163	  // 3. Continuous masked stores.
1164	  // Analyze the mask operand to determine at runtime the size of the data we
1165	  // are moving.
1166	  MaskState mstate;
1167	  auto isContMask = mstate.parse(mask, loc, rewriter);
1168	
1169	  if (isContMask.failed()) {
1170	    return failure();
1171	  }
1172	  LLVM_DEBUG({ llvm::dbgs() << *getModuleOpFromOperation(op) << "\n"; });
1173	  auto srcSlice = mstate.getExtractSlice(val, loc, rewriter);
1174	  auto dstSubview = mstate.getSubview(ptr, loc, rewriter);
1175	  auto storeOp = rewriter.create<bufferization::MaterializeInDestinationOp>(
1176	      loc, srcSlice, dstSubview);
1177	  storeOp.setWritable(true);
1178	  rewriter.eraseOp(op);
1179	  return success();
1180	}
1181	
1182	bool ReinterpretCastStrideCanonicalizer::hasFixableZeroStride(
1183	    memref::ReinterpretCastOp op) {
1184	  auto staticSizes = op.getStaticSizes();
1185	  auto staticStrides = op.getStaticStrides();
1186	  auto dynamicStrides = op.getStrides();
1187	
1188	  if (staticSizes.size() != staticStrides.size())
1189	    return false;
1190	
1191	  // now handle: size all static
1192	  if (llvm::any_of(staticSizes, ShapedType::isDynamic))
1193	    return false;
1194	
1195	  unsigned dynStrideIdx = 0;
1196	  for (unsigned i = 0; i < staticStrides.size(); ++i) {
1197	    // now handle: dynamic stride 0 with static size 1
1198	    if (!ShapedType::isDynamic(staticStrides[i]))
1199	      continue;
1200	
1201	    if (dynStrideIdx >= dynamicStrides.size())
1202	      return false;
1203	
1204	    Value st = dynamicStrides[dynStrideIdx];
1205	    dynStrideIdx++;
1206	    if (staticSizes[i] == 1 && mlir::isZero(OpFoldResult(st)))
1207	      return true;
1208	  }
1209	  return false;
1210	}
1211	
1212	LogicalResult ReinterpretCastStrideCanonicalizer::matchAndRewrite(
1213	    memref::ReinterpretCastOp op, PatternRewriter &rewriter) const {
1214	  if (!hasFixableZeroStride(op))
1215	    return failure();
1216	
1217	  auto staticSizes = op.getStaticSizes();
1218	  auto staticStrides = op.getStaticStrides();
1219	  auto dynamicStrides = op.getStrides();
1220	
1221	  SmallVector<Value> newDynamicStrides;
1222	  newDynamicStrides.reserve(dynamicStrides.size());
1223	
1224	  unsigned dynStrideIdx = 0;
1225	  bool changed = false;
1226	  Value c1 =
1227	      rewriter.create<arith::ConstantOp>(op.getLoc(), rewriter.getIndexAttr(1));
1228	
1229	  for (unsigned i = 0, e = staticStrides.size(); i < e; ++i) {
1230	    if (!ShapedType::isDynamic(staticStrides[i]))
1231	      continue;
1232	
1233	    if (dynStrideIdx >= dynamicStrides.size())
1234	      return failure();
1235	
1236	    Value oldStride = dynamicStrides[dynStrideIdx];
1237	    dynStrideIdx++;
1238	    if (staticSizes[i] == 1 && mlir::isZero(OpFoldResult(oldStride))) {
1239	      newDynamicStrides.push_back(c1);
1240	      changed = true;
1241	    } else {
1242	      newDynamicStrides.push_back(oldStride);
1243	    }
1244	  }
1245	
1246	  // all dynStride should be visited, and at least one should be changed
1247	  if (dynStrideIdx != dynamicStrides.size())
1248	    return failure();
1249	  if (!changed)
1250	    return failure();
1251	
1252	  auto newReinterpretCast = rewriter.create<memref::ReinterpretCastOp>(
1253	      op.getLoc(), cast<MemRefType>(op.getResult().getType()), op.getSource(),
1254	      op.getOffsets(), op.getSizes(), newDynamicStrides, op.getStaticOffsets(),
1255	      op.getStaticSizes(), op.getStaticStrides());
1256	
1257	  rewriter.replaceOp(op, newReinterpretCast.getResult());
1258	
1259	  return success();
1260	}
1261	
1262	} // namespace LoadStoreConverter
