244	class ReductionOpBaseConverter : public OpConversionPattern<OpTy> {
245	public:
246	  using OpConversionPattern<OpTy>::OpConversionPattern;
247	
248	  LogicalResult
249	  matchAndRewrite(OpTy op, typename OpTy::Adaptor adaptor,
250	                  ConversionPatternRewriter &rewriter) const final {
251	    auto sourceType =
252	        cast<RankedTensorType>(adaptor.getOperands().front().getType());
253	    assert(sourceType.hasRank() && "Expected input is ranked");
254	
255	    int64_t axis = op.getAxis();
256	    assert(axis >= 0 && axis < sourceType.getRank() &&
257	           "Expected reduction axis is within operand's rank");
258	
259	    auto realReductionOps = this->getRealReductionOps(op);
260	    if (realReductionOps.size() == 1) {
261	      return this->convertToTargetOp(op, adaptor, rewriter);
262	    }
263	    return this->convertToTargetOpExtended(op, adaptor, rewriter);
264	  }
