266	protected:
267	  llvm::SmallVector<Operation *> getReductionOps(OpTy reductionOp) const {
268	    auto reductionBody = reductionOp.getBody();
269	    return llvm::map_to_vector(reductionBody->without_terminator(),
270	                               [](Operation &op) { return &op; });
271	  }
272	
273	  llvm::SmallVector<Operation *> getRealReductionOps(OpTy reductionOp) const {
274	    auto *body = reductionOp.getBody();
275	    auto *terminator = body->getTerminator();
276	
277	    // Compute the backward slice from yielded values: only ops that
278	    // actually contribute to the computation of the reduction result
279	    // are considered.
280	    llvm::DenseSet<Operation *> liveOps;
281	    llvm::SmallVector<Value> worklist(terminator->getOperands());
282	    while (!worklist.empty()) {
283	      Value val = worklist.pop_back_val();
284	      if (auto *defOp = val.getDefiningOp()) {
285	        if (defOp->getBlock() == body && liveOps.insert(defOp).second) {
286	          for (auto operand : defOp->getOperands())
287	            worklist.push_back(operand);
288	        }
289	      }
290	    }
291	
292	    // Count only live ops, excluding type conversions that serve as
293	    // precision promotion or demotion (e.g. bf16 -> f32 -> bf16).
294	    llvm::SmallVector<Operation *> realOps;
295	    for (Operation &bodyOp : body->without_terminator()) {
296	      if (!liveOps.contains(&bodyOp))
297	        continue;
298	      if (isa<arith::ExtFOp, arith::TruncFOp, arith::BitcastOp>(&bodyOp))
299	        continue;
300	      realOps.push_back(&bodyOp);
301	    }
302	    return realOps;
303	  }
