307	                                 Location loc, Type constantType) const {
308	    // for multiop reduce of 1 element result is defined as exactly this element
309	    // for multiop reduce of tensor with N elements default value
310	    // is not involved in result computation
311	    auto reductionOps = this->getReductionOps(op);
312	    assert(reductionOps.size() == 1);
313	    auto reductionOp = reductionOps.front();
314	
315	    assert(constantType.isIntOrFloat());
316	
317	    if (constantType.isInteger()) {
318	      return rewriter.create<arith::ConstantOp>(
319	          loc, constantType, rewriter.getIntegerAttr(constantType, 0));
320	    }
321	    return rewriter.create<arith::ConstantOp>(
322	        loc, constantType, rewriter.getFloatAttr(constantType, 0.f));
