325	  arith::ConstantOp getReductionBaseConstOp(ConversionPatternRewriter &rewriter,
326	                                            Operation *reductionOp,
327	                                            Type constantType) const {
328	    const int64_t bitWidth = constantType.getIntOrFloatBitWidth();
329	
330	    auto attr =
331	        llvm::TypeSwitch<Operation *, TypedAttr>(reductionOp)
332	            .Case([&](arith::AddFOp) {
333	              return rewriter.getFloatAttr(constantType, 0.f);
334	            })
335	            .Case([&](arith::AddIOp) {
336	              return rewriter.getIntegerAttr(constantType, 0);
337	            })
