339	              return rewriter.getFloatAttr(constantType, 1.f);
340	            })
341	            .Case([&](arith::MulIOp) {
342	              return rewriter.getIntegerAttr(constantType, 1);
343	            })
344	            .template Case<arith::MaximumFOp, arith::MaxNumFOp>([&](auto) {
345	              return rewriter.getFloatAttr(
346	                  constantType, -std::numeric_limits<float>::infinity());
347	            })
348	            .template Case<arith::MinimumFOp, arith::MinNumFOp>([&](auto) {
349	              return rewriter.getFloatAttr(
350	                  constantType, std::numeric_limits<float>::infinity());
351	            })
352	            .Case([&](arith::MinSIOp) {
353	              return rewriter.getIntegerAttr(constantType,
354	                                             llvm::maxIntN(bitWidth));
355	            })
356	            .Case([&](arith::MinUIOp) {
357	              return rewriter.getIntegerAttr(constantType,
358	                                             llvm::maxUIntN(bitWidth));
359	            })
360	            .Case([&](arith::MaxSIOp) {
361	              return rewriter.getIntegerAttr(constantType,
362	                                             llvm::minIntN(bitWidth));
363	            })
364	            .Case([&](arith::MaxUIOp) {
365	              return rewriter.getIntegerAttr(constantType, 0);
366	            })
367	            .Case([&](arith::OrIOp) {
368	              return rewriter.getIntegerAttr(constantType, 0);
369	            })
370	            .Case([&](arith::AndIOp) {
371	              return rewriter.getIntegerAttr(constantType, 1);
372	            })
373	            .Case([&](arith::XOrIOp) {
