               pred == arith::CmpIPredicate::ugt ||
               pred == arith::CmpIPredicate::ult) {
      if (cmpOp.getLhs() == block->getArgument(0) &&
          cmpOp.getRhs() == block->getArgument(2)) {
        cmpIOp = cmpOp;
        return WalkResult::interrupt();
      }
    }
    return WalkResult::advance();
  });
