}

TypedAttr valueAttr;
if (isa<mlir::FloatType>(valueType)) {
  valueAttr = rewriter.getFloatAttr(valueType, T::getBaseReductionValue());
} else if (isa<mlir::IntegerType>(valueType)) {
  if (isUnsigned) {
    valueAttr =
        rewriter.getIntegerAttr(valueType, T::getBaseReductionUIntValue());
